const euro=(c)=>((c??0)/100).toFixed(2).replace('.',',');
const longDate=new Intl.DateTimeFormat('de-DE',{timeZone:'Europe/Berlin',dateStyle:'medium',timeStyle:'short'}),shortDate=new Intl.DateTimeFormat('de-DE',{timeZone:'Europe/Berlin',day:'2-digit',month:'2-digit'}),dayKey=new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Berlin',year:'numeric',month:'2-digit',day:'2-digit'});
const date=(s,short=false)=>s?(short?shortDate:longDate).format(new Date(s)):'—';
const STATES=['Preise prüfen','Angebot offen','Angenommen','Termin verbindlich','In Arbeit','Erledigt','Bezahlt','Abgelehnt','Storniert','Abgelaufen'];
let state={orders:[],jobs:[],integrations:{},settings:{}},view='overview',selected=null,tab='source',synthetic=false,filter='Alle',query='',calendarOffset=0,protocolDraft=null,replacing=null,customers=[],customerQuery='',customerTimer=null,chatThread=null;
const icons={home:'M3 10 12 3l9 7M5 9v11h14V9M9 20v-7h6v7',orders:'M5 5h14v16H5zM9 3h6v4H9zM8 11h8M8 15h5',people:'M16 21v-3a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v3M9 10a4 4 0 1 0 0-8 4 4 0 0 0 0 8M22 21v-3a4 4 0 0 0-3-4M16 2a4 4 0 0 1 0 8',calendar:'M4 5h16v16H4zM8 3v4M16 3v4M4 10h16M8 14h1M13 14h1',docs:'M6 3h8l4 4v14H6zM14 3v5h4M9 12h6M9 16h6',money:'M3 6h18v12H3zM12 9a3 3 0 1 0 0 6 3 3 0 0 0 0-6M6 10v4M18 10v4',care:'M4 4h16v12H9l-5 4zM8 8h8M8 12h5',chat:'M21 12a8 8 0 0 1-11.6 7.1L4 20l1-4.6A8 8 0 1 1 21 12zM8 12h.01M12 12h.01M16 12h.01',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2',lock:'M6 11h12v10H6zM8 11V7a4 4 0 0 1 8 0v4M12 15v2',plus:'M12 5v14M5 12h14',arrow:'M4 12h16M14 6l6 6-6 6',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18M12 7v5l3 2',warn:'M12 3 2 21h20zM12 9v5M12 17v1',check:'M4 12l5 5L20 6',car:'M4 15h16l-2-7H6zM3 15v5M21 15v5M6 17h1M17 17h1M7 8l1-4h8l1 4',mail:'M3 5h18v14H3zM3 5l9 7 9-7',menu:'M4 6h16M4 12h16M4 18h16',back:'M20 12H4M10 6l-6 6 6 6'};
const icon=(n)=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[n]??icons.docs}"/></svg>`;
const menus=[['overview','home','Übersicht'],['orders','orders','Anfragen & Aufträge'],['trash','orders','Papierkorb'],['chat','chat','Nachrichten'],['customers','people','Kunden'],['calendar','calendar','Kalender'],['protocols','docs','Fahrzeugprotokolle'],['finance','money','Rechnungen & Zahlung'],['care','care','Kundenbetreuung'],['dilution','docs','Mischrechner'],['settings','settings','Einstellungen']];
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('visible');setTimeout(()=>$('#toast').classList.remove('visible'),7000);}
async function api(path,data){const r=await fetch('/api/'+path,{method:data===undefined?'GET':'POST',headers:data===undefined?{}:{'Content-Type':'application/json'},body:data===undefined?undefined:JSON.stringify(data),credentials:'same-origin'});const d=await r.json().catch(()=>({error:r.status===413?'Datei ist zu groß.':'Verbindung nicht lesbar.'}));if(!r.ok)throw Object.assign(Error(d.error??'Verbindung fehlgeschlagen.'),{status:r.status});return d;}
async function openOrder(id){selected=await api('order/'+encodeURIComponent(id));tab='source';replacing=null;history.replaceState(null,'','#auftrag='+id);render();}
async function refresh(){state=await api('state');if(selected)selected=await api('order/'+encodeURIComponent(selected.id)).catch(()=>null);render();}
function list(){const q=query.toLowerCase();return state.orders.filter(o=>o.synthetic===synthetic).filter(o=>(o.wg+' '+o.source.name+' '+o.source.vehicle+' '+o.source.phone+' '+(o.source.plate??'')).toLowerCase().includes(q));}
function badge(status){return `<span class="badge ${['Preise prüfen','Angebot offen'].includes(status)?'warn':['Erledigt','Bezahlt'].includes(status)?'good':['Abgelehnt','Storniert','Abgelaufen'].includes(status)?'bad':''}">${esc(status)}</span>`;}
function next(o){if(o.status==='Angenommen'&&o.appointment&&!o.appointment.confirmation)return 'Terminbestätigung abwarten: Kunde bestätigt im Kundenportal oder unterschreibt vor Ort';return ({'Preise prüfen':'Fahrzeugzustand und Preise prüfen','Angebot offen':'Kundenannahme abwarten oder vor Ort unterschreiben lassen','Angenommen':'Termin festlegen','Termin verbindlich':'Annahmeprotokoll erstellen','In Arbeit':'Arbeit abschließen und Rückgabe dokumentieren','Erledigt':'Schlussrechnung und Zahlung','Bezahlt':'Auftrag abgeschlossen'})[o.status]??'Auftrag geschlossen';}
function empty(title,subtitle,button=''){return `<div class="empty"><div class="emptyicon">${icon('orders')}</div><strong>${esc(title)}</strong><p>${esc(subtitle)}</p>${button}</div>`;}
function heading(title,sub,actions=''){return `<div class="heading"><div><div class="eyebrow">White Gloss Detailing · Horb am Neckar</div><h1>${title}</h1><p>${sub}</p></div><div class="actions">${actions}</div></div>`;}
function notice(title,body,blue=false){return `<div class="notice ${blue?'blue':''}">${icon(blue?'lock':'warn')}<div><strong>${title}</strong>${body}</div></div>`;}
function table(orders){return orders.length?`<div class="tablewrap"><table class="order-table" role="table"><thead><tr><th scope="col">Auftrag / Kunde</th><th>Fahrzeug</th><th>Status</th><th>Nächster Schritt</th><th>Festpreis</th><th></th></tr></thead><tbody>${orders.map(o=>`<tr data-order="${o.id}"><td><strong>${esc(o.wg)}</strong><span class="sub">${esc(o.source.name||'Ohne Namen')}</span></td><td>${esc(o.source.vehicle)}<span class="sub">${esc([o.source.plate,packageName(o.source.package)].filter(Boolean).join(' · '))}</span></td><td>${badge(o.status)}${o.pending&&Object.keys(o.pending).length?' <span class="badge warn">Unterschrift offen</span>':''}</td><td>${esc(next(o))}</td><td class="money">${o.offer?money(o.offer.totalCents):'Noch offen'}</td><td><button class="smallbtn" data-order="${o.id}">Öffnen</button></td></tr>`).join('')}</tbody></table></div>`:empty('Noch keine Aufträge',synthetic?'Erstelle einen eindeutig markierten Testauftrag. Es werden keine Kundennachrichten, Rechnungen oder Zahlungen ausgelöst.':'Website-Anfragen werden nach geprüfter Verbindung übernommen. Neue Aufträge legst du hier oder in der Vor-Ort-App an.',`<button data-click="create">${icon('plus')} ${synthetic?'Testauftrag':'Anfrage'} anlegen</button>`);}
function render(){const name=selected?selected.wg:menus.find(m=>m[0]===view)?.[2]??'Übersicht';$('#app').innerHTML=`<div class="layout"><aside class="sidebar" id="panelNavigation"><button class="sidebar-close" data-click="menuClose" aria-label="Menü schließen">×</button><div class="brand"><span class="brandmark">WG</span><div><strong>White Gloss</strong><small>MEIN PANEL</small></div></div><div class="navgroup">DEIN BETRIEB</div><nav class="nav" aria-label="Hauptnavigation">${menus.filter(m=>m[0]!=='chat'||state.settings.standaloneAuth).map(m=>`<button data-view="${m[0]}" class="${m[0]===view&&!selected?'active':''}" ${m[0]===view&&!selected?'aria-current="page"':''}>${icon(m[1])}${m[2]}${m[0]==='chat'?'<span class="navcount" data-chat-count hidden></span>':''}</button>`).join('')}<a class="navlink" href="/vor-ort">${icon('car')}Vor-Ort-App</a></nav><footer><strong>White Gloss Detailing</strong>Horb am Neckar<br><br><span class="private">${icon('lock')} Privater Betreiberzugang</span></footer></aside><button class="sidebar-backdrop" data-click="menuClose" aria-label="Menü schließen" hidden></button><main class="workspace"><header class="topbar"><button class="mobile-menu" data-click="menu" aria-label="Menü öffnen" aria-expanded="false" aria-controls="panelNavigation">${icon('menu')}</button><div class="crumb">Mein Panel <span> / </span> <strong>${esc(name)}</strong></div><div class="top-actions"><span class="headerdate">${new Intl.DateTimeFormat('de-DE',{timeZone:'Europe/Berlin',day:'numeric',month:'long',year:'numeric'}).format(new Date())}</span><div class="search"><input id="search" placeholder="Auftrag, Kunde oder Kennzeichen …" aria-label="Auftrag, Kunde oder Kennzeichen suchen" value="${esc(query)}"></div><button class="testswitch ${synthetic?'on':''}" data-click="test" aria-pressed="${synthetic}">${synthetic?'Testbereich aktiv':'Testbereich'}</button>${state.settings.standaloneAuth?'<button class="smallbtn" data-click="logout">Abmelden</button>':'<span class="avatar" title="Betreiber">WG</span>'}</div></header>${synthetic?'<div class="testbanner">Synthetische Testdaten · getrennte TEST-Nummern · kein Versand und keine Rechnungen</div>':''}<div class="content" id="content">${selected?detail():screen()}</div></main>${mobileNavigation()}</div>`;mountDetail();mountDilutionCalculator($('#content'));$('#search')?.addEventListener('input',e=>{query=e.target.value;if(selected||view==='chat'){selected=null;view='orders';history.replaceState(null,'','#');render();$('#search').focus();$('#search').setSelectionRange(query.length,query.length);return;}$('#content').innerHTML=screen();mountDilutionCalculator($('#content'));});if(view==='customers'&&!selected)mountCustomers();if(view==='overview'&&!selected&&$('#portaloverview'))loadPortalOverview($('#portaloverview'));if(view==='chat'&&!selected&&state.settings.standaloneAuth){mountInbox($('#chatroot'),{synthetic,threadId:chatThread,toast});chatThread=null;}else leaveInbox();setBadge();}
function mobileNavigation(){const items=[['overview','home','Start'],['orders','orders','Aufträge'],['calendar','calendar','Kalender'],['dilution','docs','Mischen']];return `<nav class="mobile-dock" aria-label="Mobile Hauptnavigation">${items.map(([id,ic,label])=>`<button data-view="${id}" ${!selected&&view===id?'aria-current="page"':''}>${icon(ic)}<span>${label}</span></button>`).join('')}<button data-click="menu" aria-label="Alle Bereiche öffnen" aria-expanded="false" aria-controls="panelNavigation">${icon('menu')}<span>Mehr</span></button></nav>`;}
let menuOpener=null;
function setMenu(open,opener=null){if(open)menuOpener=opener??document.activeElement;const sidebar=$('.sidebar');sidebar?.classList.toggle('open',open);const backdrop=$('.sidebar-backdrop');if(backdrop)backdrop.hidden=!open;for(const button of document.querySelectorAll('[data-click="menu"]'))button.setAttribute('aria-expanded',String(open));if(open)sidebar?.querySelector('.sidebar-close')?.focus();else (menuOpener?.isConnected?menuOpener:$('.mobile-menu'))?.focus();}
document.addEventListener('keydown',event=>{const sidebar=$('.sidebar.open');if(!sidebar)return;if(event.key==='Escape'){setMenu(false);return;}if(event.key!=='Tab')return;const controls=[...sidebar.querySelectorAll('button,a[href]')];const first=controls[0],last=controls.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}});
function mountDetail(){if(!selected)return;for(const form of document.querySelectorAll('#priceform,#appointmentform'))bookingFormStates.set(form,bookingFormState(form));const portalBox=$('#portalrequests');if(portalBox)loadPortalRequests(portalBox,selected.id);mountPricing($('#priceform'));mountProtocolForm($('#protocolform'));mountProtocolForm($('#replacementform'));if(tab==='price'){const gallery=$('#websitephotos');if(gallery&&state.settings.standaloneAuth)loadBookingPhotos(gallery,selected.id);}}
// Übersicht: alle offenen Kundenwünsche, auch wenn der Chat eines Auftrags beendet ist.
async function loadPortalOverview(box){try{const {requests}=await api('portal-admin/requests');if(!box.isConnected)return;const open=requests.filter(r=>r.synthetic===synthetic);box.innerHTML=open.length?notice(open.length+' offene Kundenwünsche aus dem Kundenportal','<ul class="timeline">'+open.map(r=>`<li><small>${date(r.createdAt)} · ${esc(r.wg)} · ${esc(r.name)}</small>${r.kind==='extras'?'Zusatzleistungen: '+esc((r.extras??[]).map(e=>e.name).join(', ')):'Terminwunsch: '+esc(r.wish??'')} <button class="smallbtn" data-order="${esc(r.orderId)}">Auftrag öffnen</button></li>`).join('')+'</ul>'):'';}catch{box.innerHTML='';}}
// Kundenwünsche aus dem Kundenportal (Zusatzleistungen, Terminwünsche) im Auftrag anzeigen.
const portalStatus={offen:'offen',übernommen:'übernommen',erledigt:'erledigt',abgelehnt:'abgelehnt'};
async function loadPortalRequests(box,id){try{const {requests}=await api('portal-admin/requests?order='+encodeURIComponent(id));if(!box.isConnected||selected?.id!==id)return;const open=requests.filter(r=>r.status==='offen');if(!requests.length){box.innerHTML='';return;}box.innerHTML=`<div class="notice ${open.length?'':'blue'}">${icon(open.length?'warn':'lock')}<div><strong>${open.length?open.length+' offene Kundenwünsche aus dem Kundenportal':'Kundenwünsche aus dem Kundenportal'}</strong><ul class="timeline">${requests.map(r=>`<li><small>${date(r.createdAt)} · ${r.kind==='extras'?'Zusatzleistungen':'Terminwunsch'} · ${esc(portalStatus[r.status]??r.status)}</small>${r.kind==='extras'?esc((r.extras??[]).map(e=>e.name+' ('+(e.inspect?'ab ':'')+money(e.priceCents)+')').join(', ')):esc(r.wish??'')}${r.note?'<br>Hinweis: '+esc(r.note):''}${r.status==='offen'?`<div class="actions">${r.kind==='extras'?`<button class="smallbtn primary" data-click="portalRequest" data-request="${esc(r.id)}" data-decision="apply">In Leistungen übernehmen</button>`:`<button class="smallbtn" data-click="portalRequest" data-request="${esc(r.id)}" data-decision="done">Erledigt</button>`}<button class="smallbtn danger" data-click="portalRequest" data-request="${esc(r.id)}" data-decision="decline">Ablehnen</button></div>`:''}</li>`).join('')}</ul><small>Der Kunde sieht den Status im Portal. Benachrichtige ihn bei Bedarf im Kundenchat.</small></div></div>`;}catch{box.innerHTML='';}}
async function loadBookingPhotos(gallery,id){try{gallery.textContent='Buchungsaufnahmen werden geladen …';const photoData=await api(state.settings.standaloneAuth?'bookingphotos?id='+encodeURIComponent(id):'websitephotos/'+id);const photos=Array.isArray(photoData)?photoData:photoData.photos;if(!gallery.isConnected)return;gallery.innerHTML=photos.length?photos.map(p=>p.mime.startsWith('image/')?`<a href="${esc(p.url)}" target="_blank" rel="noreferrer"><img src="${esc(p.url)}" alt="${esc(p.name)}"></a>`:`<video controls preload="metadata" src="${esc(p.url)}" aria-label="${esc(p.name)}"></video>`).join(''):'<p class="hint">Keine Buchungsaufnahmen vorhanden.</p>';if(photoData.warning)gallery.insertAdjacentHTML('beforeend','<p class="hint">'+esc(photoData.warning)+' · Geschützte Kopien bleiben verfügbar.</p>');}catch(error){gallery.textContent=error.message;}}
function screen(){switch(view){case'overview':return overview();case'orders':return ordersPage();case'trash':return trashPage();case'customers':return customersPage();case'calendar':return calendarPage();case'protocols':return protocolsPage();case'finance':return financePage();case'care':return carePage();case'chat':return state.settings.standaloneAuth?'<div id="chatroot" class="chatroot"></div>':overview();case'settings':return settingsPage();case'dilution':return heading('Mischverhältnisrechner','Konzentrat und Wasser passend für deine fertige Mischung berechnen.')+'<section class="card formsection">'+dilutionCalculatorHTML()+'</section>';default:return overview();}}
function overview(){const orders=list(),open=orders.filter(o=>!['Bezahlt','Abgelehnt','Storniert','Abgelaufen'].includes(o.status)),price=orders.filter(o=>o.status==='Preise prüfen'),appointments=orders.filter(o=>o.appointment&&['Termin verbindlich','In Arbeit'].includes(o.status)).sort((a,b)=>a.appointment.start.localeCompare(b.appointment.start));const revenue=orders.filter(o=>o.status==='Bezahlt').reduce((n,o)=>n+(billingTotal(o)??0),0);const pending=orders.filter(o=>o.pending&&Object.keys(o.pending).length);return heading('Dein Betrieb im Blick','Anfragen prüfen, Kunden begleiten und jeden Auftrag sicher abschließen.',`<a class="button" href="/vor-ort">${icon('car')} Vor-Ort-App</a><button data-click="refresh">Aktualisieren</button><button class="primary" data-click="create">${icon('plus')} ${synthetic?'Testauftrag':'Neue Anfrage'}</button>`)+(state.settings.standaloneAuth?'<div id="portaloverview"></div>':'')+(!state.settings.numberAudit&&!synthetic?notice('Einrichtung abschließen','Für echte Aufträge fehlt noch der WG-Nummernabgleich. <a href="#settings" data-view="settings">Einstellungen öffnen →</a>'):'')+(pending.length?notice('Dokumente warten auf Kundenunterschrift',pending.map(o=>`<br><a href="#auftrag=${o.id}" data-order="${o.id}">${esc(o.wg)} · ${esc(o.source.name)}</a>`).join('')):'')+`<div class="stats">${[[open.length,'Offene Aufträge','Von der Anfrage bis zur Rückgabe','orders'],[price.length,'Preise prüfen','Deine Begutachtung ist gefragt','car'],[appointments.length,'Termine & laufende Arbeiten','Verbindlich oder in Arbeit','calendar'],[money(revenue),'Vollständig bezahlt','Summe der bezahlten Aufträge','money']].map(([value,title,foot,ic])=>`<div class="card stat"><div class="top">${title}${icon(ic)}</div><div class="value money">${value}</div><div class="foot">${foot}</div></div>`).join('')}</div><div class="columns"><div><section class="card"><div class="card-title"><h2>Deine nächsten Schritte</h2><small>${open.length} offene Aufträge</small></div>${table(open.slice(0,8))}</section><section class="card sectiongap"><div class="card-title"><h2>Anstehende Termine</h2><button class="smallbtn" data-view="calendar">Kalender öffnen →</button></div>${appointments.length?appointments.slice(0,6).map(o=>`<div class="calendar-day" data-order="${o.id}"><strong>${date(o.appointment.start)}</strong><div class="calendar-item">${esc(o.wg)} · ${esc(o.source.name)}<br>${esc(o.source.vehicle)} · ${esc(o.appointment.delivery)}</div></div>`).join(''):empty('Noch keine Termine','Termine legst du im Auftrag fest oder direkt bei der Sofort-Buchung vor Ort.')}</section></div><div><section class="card"><div class="card-title"><h2>Verbindungen & Freigaben</h2>${icon('lock')}</div><div class="card-body">${[['website','Website-Anfragen'],['calendar','Kalender'],['email','E-Mail-Versand'],['qonto','Qonto · Rechnungen'],['customer','Kundenannahme'],['background','Hintergrundlauf']].map(([k,name])=>`<div class="integration"><div class="row"><span>${name}</span><span class="badge ${state.integrationReady?.[k]?'good':'warn'}">${state.integrationReady?.[k]?'Geprüft':'Einrichtung offen'}</span></div><p>${esc(state.integrations[k])}</p></div>`).join('')}<button data-view="settings" class="sectiongap">Einrichtung bearbeiten →</button></div></section><section class="card sectiongap"><div class="card-title"><h2>Dein Buchungsablauf</h2></div><div class="card-body"><ol class="step-list">${[['Kunde & Fahrzeug','Aus dem Kundenstamm wählen oder neu anlegen'],['Leistungen & Preis','Paket, Extras und Zuschläge festlegen'],['Annahme','Unterschrift vor Ort oder persönlicher Angebotslink'],['Annahmeprotokoll','Fotos, Schäden, Lackschichtdicke'],['Rückgabe & Zahlung','Rückgabeprotokoll, Rechnung und Zahlung']].map(([t,s],i)=>`<li><span class="num">${i+1}</span><div>${t}<br><small>${s}</small></div></li>`).join('')}</ol><p class="hint">Jeder Schritt bleibt bearbeitbar. Unterschriebene Dokumente werden nur durch ein neu unterschriebenes Ersatzdokument ersetzt.</p></div></section></div></div><div class="endnote">Europe/Berlin · Gelöschte Aufträge bleiben im Papierkorb wiederherstellbar</div>`;}
function trashPage(){const q=query.toLowerCase();const os=(state.trash??[]).filter(o=>o.synthetic===synthetic).filter(o=>(o.wg+' '+o.source.name+' '+o.source.vehicle).toLowerCase().includes(q));return heading('Papierkorb','Gelöschte Aufträge wiederherstellen. Dokumente, Fotos und Rechnungen bleiben erhalten.')+notice('Kundenlinks und automatische Abläufe pausieren','Bisherige Kundenlinks bleiben gesperrt; vorbereiteter Versand wird nicht automatisch wiederholt. Neue fällige Abläufe folgen deinen bestehenden Freigaben.',true)+(os.length?table(os):empty('Papierkorb ist leer','Gelöschte Aufträge erscheinen hier.'));}
function trashDetail(o){return heading(esc(o.wg)+' · Papierkorb',esc(o.source.name||'Ohne Namen'),'<button data-click="back">Zurück</button><button class="primary" data-click="restoreOrder">Auftrag wiederherstellen</button>')+notice('Auftrag gelöscht',date(o.trash.deletedAt)+(o.trash.reason?' · '+esc(o.trash.reason):'')+'. Zum Bearbeiten zuerst wiederherstellen.')+'<section class="card formsection">'+pairs({'Kunde':o.source.name,'Fahrzeug':o.source.vehicle,'Status':o.status})+['intake','return'].filter(k=>o[k]).map(k=>'<details class="protocolreview"><summary>'+ (k==='intake'?'Annahmeprotokoll':'Übergabeprotokoll')+'</summary>'+protocolSummaryHTML(o[k],{kind:k})+signatureImage(o[k].customerSignature)+(state.settings.standaloneAuth?'<a class="button" href="/api/protocol/pdf?id='+encodeURIComponent(o.id)+'&kind='+k+'">PDF</a>':'')+historyHTML(o,k)+'</details>').join('')+(o.invoice?invoiceResultHTML(o).replace(/<button\b[^>]*>[\s\S]*?<\/button>/g,''):'')+'<button data-click="audit">Änderungsprotokoll ansehen</button></section>';}
function ordersPage(){return heading('Anfragen & Aufträge','Alle Aufträge mit Status und nächstem Schritt.',`<button data-click="import">Website-Anfragen übernehmen</button><button class="primary" data-click="create">${icon('plus')} ${synthetic?'Testauftrag':'Neue Anfrage'}</button>`)+`<section class="card"><div class="toolbar">${['Alle',...STATES].map(s=>`<button data-filter="${s}" class="${filter===s?'active':''}">${s}</button>`).join('')}</div>${table(list().filter(o=>filter==='Alle'||o.status===filter))}</section>`;}
const digits=value=>String(value??'').replace(/[^0-9+]/g,'');
const whatsapp=phone=>{let d=digits(phone).replace(/^\+/,'');if(d.startsWith('00'))d=d.slice(2);else if(d.startsWith('0'))d='49'+d.slice(1);return d.length>=8?'https://wa.me/'+d:'';};
const maps=address=>address?'https://www.google.com/maps/dir/?api=1&destination='+encodeURIComponent(address):'';
function contactLinks(c){const wa=whatsapp(c.phone),map=maps([c.address,c.city].filter(Boolean).join(', '));return `${c.phone?`<a class="button" href="tel:${esc(digits(c.phone))}">Anrufen</a>`:''}${wa?`<a class="button" href="${esc(wa)}" target="_blank" rel="noreferrer">WhatsApp</a>`:''}${c.email?`<a class="button" href="mailto:${esc(c.email)}">E-Mail</a>`:''}${map?`<a class="button" href="${esc(map)}" target="_blank" rel="noreferrer">Navigation</a>`:''}`;}
function customersPage(){return heading('Deine Kunden','Kundenstamm mit Fahrzeugen. Kunden werden nie gelöscht.',`<button class="primary" data-click="newCustomer">${icon('plus')} Neuer Kunde</button>`)+`<section class="card"><div class="toolbar"><input id="customer-search" type="search" placeholder="Name, Telefon, E-Mail oder Kennzeichen …" aria-label="Kunden suchen" value="${esc(customerQuery)}"></div><div id="customer-list">${customerCards()}</div></section>`;}
function customerCards(){return customers.length?`<div class="grid3">${customers.map(c=>`<div class="card customer-card"><h3>${esc(c.name||c.company||'Ohne Namen')}</h3><p>${esc(c.company&&c.name?c.company:'')}${c.company&&c.name?'<br>':''}${esc(c.email||'Keine E-Mail')}<br>${esc(c.phone||'Keine Telefonnummer')}</p>${c.vehicles.length?`<p class="hint">${c.vehicles.map(v=>esc([v.label,v.plate].filter(Boolean).join(' · '))).join('<br>')}</p>`:''}<span class="badge">${c.orderCount} ${c.orderCount===1?'Auftrag':'Aufträge'}</span><div class="actions sectiongap">${contactLinks(c)}<button class="smallbtn" data-customer="${c.id}">Kundenakte</button><button class="smallbtn" data-new-order="${c.id}">Neue Anfrage</button></div></div>`).join('')}</div>`:empty(customerQuery?'Kein Kunde gefunden':'Dein Kundenstamm ist noch leer',customerQuery?'Suche anpassen oder neuen Kunden anlegen.':'Kunden entstehen mit jeder Anfrage oder werden hier angelegt.');}
async function loadCustomers(){try{customers=(await api('customers?q='+encodeURIComponent(customerQuery)+(synthetic?'&test=true':''))).customers;const target=$('#customer-list');if(target)target.innerHTML=customerCards();}catch(error){toast(error.message);}}
function mountCustomers(){loadCustomers();$('#customer-search')?.addEventListener('input',e=>{customerQuery=e.target.value;clearTimeout(customerTimer);customerTimer=setTimeout(loadCustomers,250);});}
const customerFields=c=>`<div class="grid2">${input('Name','name','text',c.name)}${input('Firma','company','text',c.company)}${input('Telefon','phone','tel',c.phone)}${input('E-Mail','email','email',c.email)}${input('Adresse','address','text',c.address)}${input('Ort','city','text',c.city)}</div>${input('Abweichende Rechnungsadresse','billingAddress','text',c.billingAddress)}<label>Notiz<textarea name="note">${esc(c.note)}</textarea></label><label class="check"><input type="checkbox" name="reviewConsent" ${c.reviewConsent?'checked':''}>Einwilligung zur Bewertungsmail liegt vor.</label>`;
const vehicleFields=v=>`<div class="grid2">${input('Kennzeichen','plate','text',v.plate,'autocapitalize="characters"')}${input('Bezeichnung','label','text',v.label)}${input('Marke','make','text',v.make)}${input('Modell','model','text',v.model)}${input('Farbe','color','text',v.color)}${input('Baujahr','year','number',v.year??'','min="1900" max="2100"')}${input('FIN','vin','text',v.vin)}<label>Fahrzeugklasse<select name="classId"><option value="">—</option>${vehicleClasses.map(k=>`<option value="${k.id}" ${k.id===v.classId?'selected':''}>${esc(k.label)}</option>`).join('')}</select></label></div><label>Notiz<textarea name="note">${esc(v.note)}</textarea></label>`;
async function customerModal(id){const d=id?await api('customer/'+encodeURIComponent(id)):{customer:{},vehicles:[],orders:[]};const c=d.customer;modal(id?'Kundenakte · '+esc(c.name||c.company||'Ohne Namen'):'Neuer Kunde',`<form id="customerform" data-id="${esc(c.id??'')}" data-version="${c.version??''}">${customerFields(c)}<div class="actions">${contactLinks(c)}<button class="primary" type="submit">Kunde speichern</button></div><div class="error" id="modal-error"></div></form>${id?`<div class="sectiontitle">Fahrzeuge</div>${d.vehicles.map(v=>`<details class="protocolreview"><summary>${esc([v.label,v.plate].filter(Boolean).join(' · ')||'Fahrzeug')}</summary><form class="vehicleform" data-id="${esc(v.id)}" data-version="${v.version??''}">${vehicleFields(v)}<button type="submit">Fahrzeug speichern</button><div class="error"></div></form></details>`).join('')}<details class="protocolreview"><summary>Fahrzeug hinzufügen</summary><form class="vehicleform" data-customer="${esc(c.id)}">${vehicleFields({})}<button type="submit">Fahrzeug anlegen</button><div class="error"></div></form></details><div class="sectiontitle">Aufträge</div>${d.orders.length?`<ul class="timeline">${d.orders.map(o=>`<li><a href="#auftrag=${o.id}" data-order="${o.id}">${esc(o.wg)}</a> · ${esc(o.status)}<small>${date(o.updatedAt)}</small></li>`).join('')}</ul>`:'<p class="hint">Noch keine Aufträge.</p>'}<div class="actions"><button class="primary" data-new-order="${esc(c.id)}">Neue Anfrage für diesen Kunden</button></div>${(c.history??[]).length?`<details><summary>Änderungsverlauf</summary><ul class="timeline">${c.history.slice().reverse().map(h=>`<li><small>${date(h.at)}</small>${esc(Object.entries(h.before).map(([k,v])=>k+': '+(v??'—')).join(' · '))}</li>`).join('')}</ul></details>`:''}`:''}`);}
async function newOrderFor(customerId){const d=await api('customer/'+encodeURIComponent(customerId));manualCreateModal({synthetic,modal,customer:d.customer,vehicles:d.vehicles});}
function calendarPage(){const today=new Date(dayKey.format(new Date())+'T12:00:00Z');const first=new Date(Date.UTC(today.getUTCFullYear(),today.getUTCMonth()+calendarOffset,1,12));const offset=(first.getUTCDay()+6)%7;const count=new Date(Date.UTC(first.getUTCFullYear(),first.getUTCMonth()+1,0)).getUTCDate();const byDay=new Map();for(const o of list())if(o.appointment&&!['Storniert','Abgelehnt'].includes(o.status)){const key=dayKey.format(new Date(o.appointment.start));if(!byDay.has(key))byDay.set(key,[]);byDay.get(key).push(o);}const todayKey=today.toISOString().slice(0,10);return heading('Dein Kalender','Termine in Europe/Berlin.',`<a class="button" href="/api/calendar.ics${synthetic?'?test=true':''}" download>Termine als Kalenderdatei herunterladen</a>`)+notice('Kalenderdatei für Google oder Outlook','Angenommene Termine lassen sich als private Kalenderdatei importieren. Mit verbundenem Google-Kalender werden sie automatisch abgeglichen.',true)+`<div class="monthtitle"><h2>${new Intl.DateTimeFormat('de-DE',{month:'long',year:'numeric',timeZone:'Europe/Berlin'}).format(first)}</h2><div class="actions"><button data-click="prevMonth">←</button><button data-click="today">Heute</button><button data-click="nextMonth">→</button></div></div><div class="calendar-grid">${['Mo','Di','Mi','Do','Fr','Sa','So'].map(d=>`<div class="eyebrow">${d}</div>`).join('')}${Array.from({length:offset},()=>'<div class="calendar-cell"></div>').join('')}${Array.from({length:count},(_,i)=>{const day=new Date(Date.UTC(first.getUTCFullYear(),first.getUTCMonth(),i+1,12)).toISOString().slice(0,10);return `<div class="calendar-cell ${day===todayKey?'today':''}">${i+1}${(byDay.get(day)??[]).map(o=>`<div class="calendar-item" data-order="${o.id}">${o.appointment.confirmation||!['Preise prüfen','Angebot offen','Angenommen'].includes(o.status)?'':'◌ vorgeschlagen<br>'}${date(o.appointment.start)}<br>${esc(o.source.name)}<br>${esc(o.source.vehicle)}</div>`).join('')}</div>`;}).join('')}</div>`;}
function protocolsPage(){const os=list().filter(o=>o.intake||o.return||o.pending?.intake||o.pending?.return);return heading('Fahrzeugprotokolle','Annahme und Rückgabe mit Fotos, Schäden, Lackschichtdicke und Unterschriften.')+notice('Protokolle gehören zum Auftrag','Öffne einen Auftrag, um Annahme oder Rückgabe zu dokumentieren. Unterschriebene Protokolle werden nur durch ein neu unterschriebenes Ersatzprotokoll ersetzt.',true)+(os.length?table(os):empty('Noch keine Fahrzeugprotokolle','Das Annahmeprotokoll erstellst du im Auftrag oder in der Vor-Ort-App.'));}
function financePage(){const os=list().filter(o=>['Erledigt','Bezahlt'].includes(o.status)||(o.payments??[]).length);return heading('Rechnungen & Zahlung','Die WG-Nummer bleibt vom ersten Auftrag bis zur Schlussrechnung gleich.')+notice(state.integrationReady?.qonto?'Qonto-Abrechnung bereit':'Qonto-Einrichtung offen','Nach der Rückgabe: Auftrag öffnen → Zahlung & Rechnung → Abrechnen. Rechnung mit 7 Tagen Zahlungsziel oder Quittung bei Bar-/Kartenzahlung. Zahlungseingänge aus Qonto werden automatisch übernommen.',state.settings.standaloneAuth)+openInvoices()+`<section class="card"><div class="card-title"><h2>Abgeschlossene Aufträge und Zahlungen</h2></div>${table(os)}</section>`;}
function openInvoices(){const today=invoiceToday(),rows=list().filter(o=>o.invoice?.provider==='qonto'&&o.invoice.status==='unpaid'&&o.status!=='Bezahlt').sort((a,b)=>String(a.invoice.dueDate).localeCompare(String(b.invoice.dueDate)));if(!rows.length)return '';return `<section class="card sectiongap"><div class="card-title"><h2>Offene Rechnungen</h2></div><div class="card-body"><ul class="timeline">${rows.map(o=>`<li><strong>${esc(o.invoice.number)} · ${esc(o.source.name)}</strong><small>${money(o.invoice.totalCents)} · zahlbar bis ${esc(invoiceGermanDay(o.invoice.dueDate))}${o.invoice.dueDate<today?' · überfällig':''}</small><button class="smallbtn" data-order="${o.id}">Auftrag öffnen</button></li>`).join('')}</ul></div></section>`;}
function carePage(){const notes=list().flatMap(o=>(o.notes??[]).map(n=>({...n,o}))).sort((a,b)=>b.at.localeCompare(a.at));return heading('Kundenbetreuung','Notizen, Rückfragen und Wiedervorlagen im Zusammenhang mit deinen Aufträgen.')+`<div class="columns"><section class="card"><div class="card-title"><h2>Betreuungsverlauf</h2></div>${notes.length?`<div class="card-body"><ul class="timeline">${notes.map(n=>`<li><small>${date(n.at)} · ${esc(n.o.wg)} · ${esc(n.kind)}${n.followUp?' · Wiedervorlage '+esc(n.followUp):''}</small><strong>${esc(n.o.source.name)}</strong><p>${esc(n.note)}</p><button class="smallbtn" data-order="${n.o.id}">Auftrag öffnen</button></li>`).join('')}</ul></div>`:empty('Noch keine Betreuungsnotizen','Öffne eine Kundenakte und halte Telefonate, Rückfragen oder nächste Schritte fest.')}</section><section class="card"><div class="card-title"><h2>Automatische Betreuung</h2></div><div class="card-body"><ol class="step-list"><li>${icon('clock')}<div>Terminerinnerung<br><small>Höchstens einmal, innerhalb der letzten 72 Stunden vor einem verbindlichen Termin.</small></div></li><li>${icon('mail')}<div>Bewertungsmail<br><small>Nur mit Einwilligung und frühestens 168 Stunden nach „Erledigt“. Keine zweite Nachfrage.</small></div></li><li>${icon('lock')}<div>Versandschutz<br><small>Dauerhafte Sperren verhindern Wiederholungen. Unklare Providerantworten verlangen einen Abgleich.</small></div></li></ol><p class="hint">${esc(state.integrations.background)} · ${esc(state.integrations.email)}</p>${state.jobs.length?`<ul class="timeline">${state.jobs.map(j=>`<li>${esc(j.kind)} · ${esc(j.state)}<small>${esc(j.detail??j.provider_id??'')}</small></li>`).join('')}</ul>`:''}</div></section></div>`;}
function input(label,name,type='text',value='',extra=''){return `<label>${label}<input type="${type}" name="${name}" value="${esc(value)}" ${extra}></label>`;}
function settingsPage(){const s=state.settings;return heading('Einstellungen & Verbindungen','Zugänge werden verschlüsselt gespeichert. Gespeichert bedeutet noch nicht geprüft.')+`<form id="settingsform"><section class="card formsection"><h2>WG-Nummern einmalig abgleichen</h2><p>Vergleiche vor dem ersten echten Auftrag den bisherigen Buchungsbestand und vorhandene Rechnungen. Bereits verwendete Nummern werden nie wieder vergeben.</p>${s.numberAudit?notice('Nummernstand abgeglichen',esc(s.numberEvidence),true):`<div class="grid2">${input('Letzte bereits vergebene WG-Nummer','lastNumber','number',s.lastNumber,'min="0" step="1"')}<label>Abgleichnachweis<textarea name="numberEvidence" placeholder="Welche bisherigen Buchungen und Rechnungen wurden verglichen?">${esc(s.numberEvidence)}</textarea></label></div><label class="check"><input type="checkbox" name="numberAudit">Ich habe den bisherigen Nummernstand einschließlich vorhandener Rechnungen geprüft und bestätige die nächste freie Nummer.</label>`}</section><section class="card formsection"><h2>Website-Anfragen · ausschließlich lesen</h2><p class="hint">${esc(state.integrations.website)}</p><p>Beim ersten erfolgreichen Zugriff wird der Neustart festgehalten: vorhandene Anfragen werden ausgelassen. Danach maximal 40 Anfragen, neueste zuerst. Importierte Website-Angaben bleiben von deiner Begutachtung getrennt.</p>${input('Hub-Schlüssel','hubKey','password','','autocomplete="new-password" placeholder="'+(s.hubConfigured?'Bereits geschützt gespeichert · leer lassen zum Behalten':'Noch nicht hinterlegt')+'"')}<button type="button" data-check="website">Lesenden Zugriff prüfen</button><p class="hint">Keine Statusänderung, Bestätigung oder E-Mail auf white-gloss.de.</p></section><section class="card formsection"><h2>E-Mail-Versand · Resend</h2>${s.migrationReady?'<button type="button" data-click="migration">Geprüfte Zugänge verschlüsselt für IONOS übertragen</button>':''}<p>Verifizierte Absenderdomain erforderlich. Bei der Verbindungsprüfung wird keine E-Mail gesendet.</p><div class="grid2">${input('API-Schlüssel','resendKey','password','','autocomplete="new-password" placeholder="'+(s.resendConfigured?'Gespeichert · leer lassen zum Behalten':'Noch nicht hinterlegt')+'"')}${input('Verifizierte Absenderadresse','sender','email',s.sender)}</div>${input('Vorhandener Google-Bewertungslink','reviewUrl','url',s.reviewUrl)}<button type="button" data-check="email">Domain & Verbindung prüfen</button></section><section class="card formsection"><h2>Kalender</h2><p>Verbindliche Paneltermine werden nach geprüfter Google-Verbindung im Geschäftskalender angelegt oder aktualisiert. Änderungen aus Google werden nicht automatisch als Auftragsänderung übernommen.</p><div class="grid2"><label>Kalenderanbieter<select name="calendarProvider"><option ${s.calendarProvider==='Google'?'selected':''}>Google</option><option ${s.calendarProvider==='Outlook'?'selected':''}>Outlook</option></select></label>${input('Kalender-ID','calendarId','text',s.calendarId)}</div>${s.standaloneAuth?'':input('Zugriffstoken für lesende Prüfung','calendarToken','password','','autocomplete="new-password" placeholder="'+(s.calendarConfigured?'Gespeichert · leer lassen zum Behalten':'Noch nicht hinterlegt')+'"')}${s.standaloneAuth?'<button type="button" data-click="calendarConnect">Geschäftlichen Google-Kalender dauerhaft verbinden</button>':''}<button type="button" data-check="calendar">Lesenden Kalenderzugriff prüfen</button></section><section class="card formsection"><h2>Qonto · Rechnungen & Zahlungen</h2><p>Rechnungen und Quittungen stellst du im Auftrag direkt in Qonto aus. Rechnungsnummer = WG-Nummer. Zahlungseingänge, die Qonto der Rechnung zuordnet, übernimmt das Panel automatisch.</p><p class="hint">Login und Secret Key: Qonto → Einstellungen → Integrationen &amp; Partnerschaften → API-Schlüssel. Steuernummer bzw. USt-IdNr. für die Rechnungsangaben ebenfalls in Qonto hinterlegen.</p><div class="grid2">${input('Qonto-Login','qontoLogin','text',s.qontoLogin??'','autocomplete="off" maxlength="200" placeholder="z. B. white-gloss-1234"')}${input('Secret Key','qontoKey','password','','autocomplete="new-password" placeholder="'+(s.qontoConfigured?'Geschützt gespeichert · leer lassen zum Behalten':'Noch nicht hinterlegt')+'"')}</div>${(s.qontoAccounts??[]).length?`<label>Zahlungskonto auf der Rechnung<select name="qontoIban">${s.qontoIban?'':'<option value="">Bitte Konto auswählen</option>'}${s.qontoAccounts.map(a=>`<option value="${esc(a.iban)}" ${a.iban===s.qontoIban?'selected':''}>${esc(a.name)} · ${esc(a.iban.slice(0,4)+' … '+a.iban.slice(-4))}</option>`).join('')}</select></label>`:''}<p class="hint">${s.qontoVerified?'Verbunden'+(s.qontoCompanyName?': '+esc(s.qontoCompanyName):'')+'.':'Die Prüfung liest nur Organisation und Konten. Es wird nichts erstellt oder versendet.'}</p><div class="actions"><button type="button" data-check="qonto">Qonto-Verbindung prüfen</button><button type="button" data-click="qontoNumbers">Vorhandene Qonto-Rechnungen abgleichen</button></div><p class="hint">${s.qontoNumberCheck?esc(s.qontoNumberCheck.count+' Qonto-Rechnungen gelesen · höchste WG-Nummer '+s.qontoNumberCheck.maxNumber+' · abweichende WG-Formate '+(s.qontoNumberCheck.otherWgNumbers??0)):'Vor dem ersten echten Auftrag gleichst du den WG-Nummernstand einmalig ab.'}</p><h3>Zahlungsziel &amp; Mahnwesen</h3><p>Zahlungsziel 7 Tage. Ohne Zahlungseingang: Zahlungserinnerung 3 Tage nach Fälligkeit, 1. Mahnung nach 14 Tagen, 2. Mahnung nach 28 Tagen – jeweils mit neuer 7-Tage-Frist, ohne Mahngebühren. Automatischer Versand erst nach deiner Freigabe unter „Automatische Abläufe freigeben“.</p></section>${s.standaloneAuth?'<section class="card formsection"><h2>Dein Zugang</h2><p><a href="/auth/password">Passwort einrichten oder ändern</a></p></section><section class="card formsection"><h2>Automatische Abläufe freigeben</h2>'+[['sendApproved','Angebotsmails und automatische Kundenmails über den geprüften Absender erlauben'],['backgroundApproved','Terminerinnerungen und Bewertungsmails gemäß den festgelegten Fristen erlauben'],['autoImportApproved','Neue Website-Anfragen regelmäßig lesend übernehmen'],['calendarSyncApproved','Verbindliche Termine im geschäftlichen Google-Kalender abgleichen'],['dunningApproved','Zahlungserinnerungen und Mahnungen zu offenen Qonto-Rechnungen automatisch senden (Erinnerung +3, 1. Mahnung +14, 2. Mahnung +28 Tage nach Fälligkeit, ohne Gebühren)']].map(([key,label])=>'<label class="check"><input type="checkbox" name="'+key+'" '+(s[key]?'checked':'')+'>'+label+'</label>').join('')+'</section>':''}<section class="card formsection"><h2>Kundentexte</h2><p>Dieser Text erscheint bei jeder Annahme (vor Ort und online) mit eigenem Bestätigungsfeld. Bitte den geprüften Wortlaut deiner Widerrufsbelehrung einfügen; ohne Text wird kein Abschnitt angezeigt.</p><label>Widerrufsbelehrung<textarea name="withdrawalText" rows="8">${esc(s.withdrawalText)}</textarea></label></section><div id="settings-error" class="error"></div><button class="primary" type="submit">Einstellungen geschützt speichern</button></form><section class="card formsection sectiongap"><h2>Angebote & Fälligkeiten prüfen</h2><p>${esc(state.integrations.background)}</p><p class="hint">${esc(s.lastBackgroundError??'Der Lauf prüft abgelaufene Angebote und fällige Vorgänge. Gesperrter Versand bleibt gesperrt.')}</p><button data-click="background">Jetzt prüfen</button></section><div class="sectiongap">${s.standaloneAuth?notice('Verbindungsstatus',Object.entries(state.integrations).map(([key,value])=>key+': '+value).join(' · '),true):notice('Kundenfreigabe','Für persönliche Kundenannahmen das jeweilige Konto gezielt in Sites als Betrachter berechtigen.')}</div>`;}
function detail(){const o=selected;if(o.trash?.deletedAt)return trashDetail(o);const steps=['Preise prüfen','Angebot offen','Angenommen','Termin verbindlich','In Arbeit','Erledigt','Bezahlt'];const pending=Object.keys(o.pending??{});return `<div class="actions" data-layout="back-actions"><button data-click="back">${icon('back')} Zurück</button><button class="danger" data-click="deleteOrder">Auftrag löschen</button>${state.settings.standaloneAuth?`<button data-click="orderChat">${icon('chat')} Kundenchat</button><a class="button" href="/kunde?vorschau=${esc(o.id)}" target="_blank" rel="noopener">Kundenportal-Vorschau</a>`:''}<a class="button" href="/vor-ort#auftrag=${esc(o.id)}">In der Vor-Ort-App öffnen</a></div><section class="card"><div class="detail-header"><div class="heading" data-layout="no-bottom"><div><div class="eyebrow">${esc(o.wg)} ${o.synthetic?'· Synthetischer Testauftrag':''}</div><h2>${esc(o.source.name||'Ohne Namen')}</h2><p>${esc([o.source.vehicle,o.source.plate].filter(Boolean).join(' · ')||'Fahrzeug offen')} · ${esc(packageName(o.source.package)||'Paket noch offen')}</p></div>${badge(o.status)}</div><div class="progress">${steps.map((_,i)=>`<span class="${i<=steps.indexOf(o.status)?'done':''}"></span>`).join('')}</div></div><div class="tabs" role="tablist">${[['source','Kunde & Anfrage'],['price','Angebot & Termin'],['intake','Annahme'],['return','Rückgabe'],['payment','Zahlung & Rechnung'],['notes','Kundenakte & Status']].map(([id,name])=>`<button role="tab" aria-selected="${tab===id}" class="${tab===id?'active':''}" data-tab="${id}">${name}${pending.includes(id)||(id==='price'&&pending.includes('offer'))?' •':''}</button>`).join('')}</div><div class="detail">${state.settings.standaloneAuth?'<div id="portalrequests"></div>':''}${notice('Nächster Schritt',esc(next(o)),true)}${detailContent(o)}</div></section>`;}
function pairs(obj){return Object.entries(obj).map(([k,v])=>`<div class="fieldpair"><span>${k}</span><span>${esc(typeof v==='object'&&v!==null?JSON.stringify(v):v??'—')}</span></div>`).join('');}
function detailContent(o){switch(tab){case'source':return sourceDetail(o);case'price':return priceDetail(o);case'appointment':return appointmentDetail(o);case'intake':return protocolDetail(o,'intake');case'return':return protocolDetail(o,'return');case'payment':return paymentDetail(o);case'notes':return notesDetail(o);}return '';}
function sourceDetail(o){const s=o.source;return `<div class="actions">${contactLinks({phone:s.phone,email:s.email,address:s.address,city:s.city})}</div>${o.customer?notice('Kundenstamm',`${esc(o.customer.name||o.customer.company||'Ohne Namen')} · <button class="smallbtn" data-customer="${esc(o.customer.id)}">Kundenakte öffnen</button>`,true):notice('Nicht mit dem Kundenstamm verknüpft','<button class="smallbtn" data-click="linkCustomer">Kunden zuordnen</button>')}<form id="sourceform"><div class="sectiontitle">Kunde und Fahrzeug in diesem Auftrag</div><div class="grid2">${input('Name','name','text',s.name)}${input('Firma','company','text',s.company)}${input('Telefon','phone','tel',s.phone)}${input('E-Mail','email','email',s.email)}${input('Fahrzeug','vehicle','text',s.vehicle)}${input('Kennzeichen','plate','text',s.plate,'autocapitalize="characters"')}${input('Adresse','address','text',s.address)}${input('Ort','city','text',s.city)}${input('Wunschdatum','desiredDate','text',s.desiredDate)}${input('Zeitfenster','timeWindow','text',s.timeWindow)}</div><label>Hinweis / Wünsche<textarea name="note">${esc(s.note)}</textarea></label><label class="check"><input type="checkbox" name="reviewConsent" ${s.reviewConsent?'checked':''}>Einwilligung zur Bewertungsmail liegt vor.</label><button class="primary" type="submit">Angaben speichern</button><div class="error" id="form-error"></div></form><details class="protocolreview sectiongap"><summary>Ursprüngliche Anfrage</summary>${pairs({'Paket':packageName(s.package),'Fahrzeugklasse':className(s.vehicleClass),'Extras':extrasNames(s.extras),'Anfragebetrag':money(s.amountCents),'Abholung':(s.delivery?s.delivery+' · ':'')+money(s.pickupCents)+(s.pickupKm!==null&&s.pickupKm!==undefined?' · '+s.pickupKm+' km':'')+(s.pickupOnRequest?' · Preis auf Anfrage':''),'Website-ID':s.id??'Manuelle Anfrage'})}${s.id?'<button data-click="websitephotos">Fotos der Website-Anfrage ansehen</button><div class="photos sectiongap" id="websitephotos"></div>':''}</details>${(o.sourceHistory??[]).length?`<details class="sectiongap"><summary>Änderungsverlauf der Angaben</summary><ul class="timeline">${o.sourceHistory.slice().reverse().map(h=>`<li><small>${date(h.at)}</small>${esc(Object.entries(h.before).map(([k,v])=>k+': '+(v??'—')).join(' · '))}</li>`).join('')}</ul></details>`:''}`;}
const signatureImage=value=>value?`<img class="signature" src="${esc(String(value).startsWith('data:')?value:'/api/asset/'+value)}" alt="Unterschrift">`:'';
function pendingHTML(o,kind){const p=o.pending?.[kind];if(!p)return '';const label=(p.replaces?{offer:'Korrekturangebot',intake:'Korrektur-Annahmeprotokoll',return:'Korrektur-Übergabeprotokoll'}:{intake:'Annahmeprotokoll',return:'Übergabeprotokoll'})[kind];const link=p.token?location.origin+'/dokument/'+p.token:'';const wa=whatsapp(o.source.phone);return `<section class="card formsection sectiongap pending"><h3>${label} · wartet auf Kundenunterschrift</h3><p class="hint">Erstellt ${date(p.createdAt)}. ${p.replaces?'Nach der Unterschrift ersetzt es ausdrücklich das '+(p.replaces.signedAt?'am '+date(p.replaces.signedAt)+' ':'')+'unterschriebene Dokument. Das bisherige Dokument bleibt im Verlauf erhalten.':'Der Kunde prüft dieses Protokoll in seinem persönlichen Zugang und unterschreibt dort.'}</p>${kind==='offer'?offerLinesHTML(p.content)+`<p><strong>Gesamtfestpreis: ${money(p.content.totalCents)}</strong></p>`+priceNoteHTML():protocolSummaryHTML(p.content,{kind})}${link?`<label>Persönlicher Link für den Kunden<input readonly value="${esc(link)}"></label><p class="hint">Der Kunde meldet sich mit seiner E-Mail-Adresse an und erhält eine einmalige PIN. Der Link allein gewährt keinen Zugriff.</p>${wa?`<a class="button" target="_blank" rel="noreferrer" href="${esc(wa+'?text='+encodeURIComponent('Ihr '+label+' von White Gloss zur Unterschrift: '+link))}">Link per WhatsApp senden</a>`:''}`:''}<div class="actions">${kind==='offer'?'<button data-click="replaceOffer">Korrekturangebot aus gespeicherten Preisen aktualisieren</button>':p.replaces?'<button data-click="replaceProtocol" data-kind="'+kind+'">Korrekturentwurf bearbeiten</button>':''}<button class="primary" data-click="signPending" data-kind="${kind}">Kunde unterschreibt jetzt auf diesem Gerät</button><button data-click="documentLink" data-kind="${kind}">${link?'Neuen Link erstellen':'Link für den Kunden erstellen'}</button>${state.settings.standaloneAuth&&!o.synthetic?`<button data-click="sendDocument" data-kind="${kind}">Per E-Mail mit PIN senden</button>`:''}<button class="danger" data-click="discardPending" data-kind="${kind}">Unterschriftsanfrage verwerfen</button></div></section>`;}
function acceptanceLabel(a){if(!a)return 'Offen';const release=a.release;const label=release||a.mode==='ohne Unterschrift freigegeben'?'Ohne Unterschrift freigegeben (durch den Betrieb)':a.signature?(a.mode==='vor Ort'?'Vor Ort unterschrieben':'Online unterschrieben'):'Ohne Unterschrift angenommen';return label+' am '+date(release?.at??a.at)+(release?.reason?' · Grund: '+release.reason:'');}
function priceDetail(o){const photos=(state.settings.standaloneAuth||o.source.id&&!o.synthetic?'<div class="sectiontitle">Buchungsfotos und Kundenwünsche</div><button data-click="bookingphotos">Buchungsaufnahmen aktualisieren</button><div class="photos sectiongap" id="websitephotos"></div>':'');const offer=o.offer?`<div class="sectiontitle">${o.acceptance?.signature?'Unterschriebenes Angebot':o.acceptance?(o.acceptance.release?'Vom Betrieb freigegebenes Angebot · ohne Kundenunterschrift, weiter bearbeitbar':'Angenommenes Angebot · ohne Unterschrift, weiter bearbeitbar'):'Freigegebenes Angebot · noch nicht unterschrieben'}</div>${offerLinesHTML(o.offer)}${pairs({'Festpreis':money(o.offer.totalCents),'Gültig bis':o.acceptance?'—':date(o.offer.expiresAt),'Annahme':acceptanceLabel(o.acceptance)})}${o.offer.replaces?'<p class="notice">Dieses Angebot ersetzt ausdrücklich das zuvor unterschriebene Angebot.</p>':''}${signatureImage(o.acceptance?.signature)}${priceNoteHTML()}${o.acceptance&&state.settings.standaloneAuth?`<div class="actions"><a class="button" href="/api/protocol/pdf?id=${encodeURIComponent(o.id)}&kind=acceptance">Auftragsbestätigung (PDF)</a><button data-click="sharePdf" data-kind="acceptance">Auftragsbestätigung teilen</button></div>${protocolMailStatus(o,'acceptance')}`:''}`:'';const actions=`<div class="actions sectiongap">${!o.acceptance?.signature?`<button class="primary" data-click="onsiteAccept">${o.appointment?'Angebot & Termin gemeinsam unterschreiben':'Kunde unterschreibt jetzt vor Ort'}</button>`:''}${o.offer&&!o.acceptance&&o.offerToken?'<button data-click="offerLink">Persönlichen Angebotslink anzeigen</button>':''}${o.offer&&!o.acceptance&&o.status==='Angebot offen'&&!o.offerToken?'<button data-click="renewOfferLink">Neuen persönlichen Angebotslink erstellen</button>':''}${o.offer&&!o.acceptance&&o.status==='Angebot offen'&&state.settings.standaloneAuth&&!o.synthetic?'<button data-click="sendOffer">Angebot per E-Mail senden</button>':''}${o.acceptance?.signature&&!o.pending?.offer?'<button data-click="replaceOffer">Ersatzangebot aus gespeicherten Preisen erstellen</button>':''}</div>`;return photos+`<h2 class="sectiontitle">1 · Leistungen und Preise</h2>`+pricingHTML(o)+(state.settings.standaloneAuth?'<form id="bookingphotoform" class="sectiongap"><label>Buchungsfotos ergänzen · JPEG, PNG, WebP · je bis 15 MB<input name="bookingphotos" type="file" accept="image/jpeg,image/png,image/webp" multiple></label><button type="submit">Buchungsfotos geschützt speichern</button><div class="error" id="booking-photo-error"></div></form>':'')+(o.offerHistory?.length?`<details class="sectiongap"><summary>Frühere Angebotsfassungen (${o.offerHistory.length})</summary><ul class="timeline">${o.offerHistory.slice().reverse().map(h=>`<li><small>Ersetzt ${date(h.replacedAt)}</small>${h.offer?money(h.offer.totalCents):'—'}${h.acceptance?' · '+esc(acceptanceLabel(h.acceptance)):''}</li>`).join('')}</ul></details>`:'')+`<section class="booking-appointment sectiongap"><h2 class="sectiontitle">2 · Termin zum Angebot</h2>${appointmentDetail(o)}</section><section class="booking-signature sectiongap"><h2 class="sectiontitle">3 · Prüfen und unterschreiben</h2>${offer}${actions}${pendingHTML(o,'offer')}</section>`;}
function defaultDuration(o){const pack=o.source.packageId??o.offer?.lines?.find(l=>l.kind==='package')?.catalogId??packages.find(p=>p.name===o.source.package)?.id;return packageMinutes[pack]??120;}
function appointmentConfirmation(o){const a=o.appointment;if(!a)return '';const c=a.confirmation;if(c)return `<p class="badge good">✓ Termin bestätigt · ${esc(c.mode)} · ${date(c.at)}${c.release?.reason?' · Grund: '+esc(c.release.reason):''}</p>`;if(!['Preise prüfen','Angebot offen','Angenommen'].includes(o.status))return o.status==='Termin verbindlich'?'<p class="badge good">✓ Termin verbindlich (vor Einführung der Kundenbestätigung)</p>':'';const closed=false;return `<div class="notice">${icon('warn')}<div><strong>Termin vorgeschlagen – noch nicht bestätigt</strong>${!o.acceptance?'Der Kunde unterschreibt Angebot und Termin gemeinsam auf einer Seite.':'Verbindlich wird er erst mit der Unterschrift des Kunden (im Kundenportal oder hier vor Ort) oder mit deiner Freigabe ohne Unterschrift.'}${o.calendar?.eventId&&!o.calendar.cancelled?'<p class="hint">Der bisherige Google-Termin bleibt bis zur erneuten Bestätigung reserviert.</p>':''}${closed?'':`<div class="actions"><button type="button" class="smallbtn primary" data-click="${!o.acceptance?'onsiteAccept':'confirmAppointmentSign'}">${!o.acceptance?'Angebot & Termin unterschreiben':'Kunde unterschreibt hier'}</button><button type="button" class="smallbtn" data-click="confirmAppointmentRelease">Ohne Unterschrift verbindlich machen</button></div>`}</div></div>`;}
function appointmentDetail(o){return `${o.appointment?notice('Gespeicherter Termin',date(o.appointment.start)+' bis '+date(o.appointment.end)+' · '+esc(o.appointment.delivery)+(o.appointment.location?' · '+esc(o.appointment.location):''),true)+appointmentConfirmation(o):notice('Noch kein Termin','Wunschdatum: '+esc(o.source.desiredDate||'nicht angegeben')+(o.acceptance?'':'. Ohne Kundenannahme bleibt der Termin eine Reservierung.'))}<form id="appointmentform"><div class="grid2">${input('Datum und Uhrzeit · Europe/Berlin','start','datetime-local',o.appointment?berlinLocal(o.appointment.start):'')}${input('Dauer in Minuten','duration','number',o.appointment?.duration??defaultDuration(o),'min="15" max="4320" step="15"')}</div><div class="grid2"><label>Übergabeart<select name="delivery"><option>Kunde bringt</option><option ${o.appointment?.delivery==='Abholung'?'selected':''}>Abholung</option></select></label>${input('Ort / Adresse','location','text',o.appointment?.location??o.source.address)}</div><p class="hint">Überschneidungen werden abgelehnt. Keramikschutz: etwa 2 Tage (2880 Minuten).</p>${['In Arbeit','Erledigt','Bezahlt'].includes(o.status)?`<div class="notice">${icon('warn')}<div><strong>Der Auftrag läuft bereits</strong>Eine Terminänderung braucht deine Freigabe mit Grund (der Kunde kann jetzt nicht mehr unterschreiben). Entfernen ist nicht mehr möglich.<label class="check"><input type="checkbox" name="release">Änderung ohne neue Kundenunterschrift freigeben</label>${input('Grund','releaseReason','text','')}</div></div>`:''}<div class="actions"><button class="primary" type="submit">Termin speichern</button><button type="button" data-click="appointmentNow">Jetzt beginnen</button>${o.appointment&&!['In Arbeit','Erledigt','Bezahlt'].includes(o.status)?'<button type="button" class="danger" data-click="removeAppointment">Termin entfernen</button>':''}</div><div class="error" id="form-error"></div></form>${state.settings.standaloneAuth&&o.appointment&&o.acceptance&&['Termin verbindlich','In Arbeit','Erledigt','Bezahlt'].includes(o.status)&&!o.synthetic?'<button class="sectiongap" data-click="calendarSync">Termin bei Google abgleichen</button>':''}`;}
function protocolMailStatus(o,kind){const jobs=state.jobs.filter(j=>j.order_id===o.id&&j.kind.startsWith('protocol-'+kind));const job=jobs[0];return o.synthetic?'<p class="hint">Testauftrag: keine Kunden-E-Mail.</p>':job?`<p class="hint">${job.state==='sent'?'PDF an den Kunden versendet.':esc(job.detail??'Versandstatus im Ablaufprotokoll prüfen.')}</p>`:'<p class="hint">Kein automatischer Versand (keine Kundenunterschrift oder keine E-Mail-Adresse). Das PDF kannst du herunterladen oder teilen.</p>';}
function protocolDetail(o,kind){const saved=o[kind],label=kind==='intake'?'Annahmeprotokoll':'Rückgabeprotokoll',signed=Boolean(saved?.customerSignature);const pdf=state.settings.standaloneAuth&&saved?`<div class="actions"><a class="button" href="/api/protocol/pdf?id=${encodeURIComponent(o.id)}&kind=${kind}">PDF herunterladen</a><button data-click="sharePdf" data-kind="${kind}">PDF teilen</button></div>${protocolMailStatus(o,kind)}`:'';
  const compare=kind==='return'&&o.intake?`<details class="protocolreview"><summary>Annahmeprotokoll zum Vergleich</summary>${protocolSummaryHTML(o.intake,{kind:'intake'})}</details>`:'';
  if(signed)return `<div class="sectiontitle">Unterschriebenes ${label}</div>${protocolSummaryHTML(saved,{kind})}<div class="grid2 sectiongap"><div>Unterschrift Kunde${signatureImage(saved.customerSignature)}</div><div>Unterschrift Betrieb${signatureImage(saved.operatorSignature)||'<p class="hint">—</p>'}</div></div><p class="hint">Unterschrieben am ${date(saved.signedAt??saved.savedAt)}${saved.signedRemotely?' über den persönlichen Kundenzugang':''}. Unterschriebene Protokolle bleiben unverändert.</p>${pdf}${pendingHTML(o,kind)}${replacing===kind?`<div class="sectiontitle">Ersatzprotokoll erstellen</div><p class="hint">Das Ersatzprotokoll ersetzt das unterschriebene Protokoll erst, wenn der Kunde es unterschreibt.</p>${protocolFormHTML({kind,protocol:o.pending?.[kind]?.content??saved,order:o,company:state.company,id:'replacementform',submitLabel:'Korrekturentwurf speichern',signLabel:''})}`:'<button data-click="replaceProtocol" data-kind="'+kind+'">Korrekturprotokoll erstellen</button>'}${historyHTML(o,kind)}${compare}`;
  return `${saved?`<p class="notice">Gespeichertes ${label} · noch nicht vom Kunden unterschrieben. Du kannst es frei bearbeiten.</p>`:''}${pdf}${compare}${protocolFormHTML({kind,protocol:o.pending?.[kind]?.content??saved,order:o,company:state.company,submitLabel:saved?'Änderungen speichern':'Protokoll speichern',signLabel:'Anzeigen & unterschreiben',remoteLabel:'Kunde nicht vor Ort · zur Unterschrift vorbereiten'})}${pendingHTML(o,kind)}${historyHTML(o,kind)}`;}
function historyHTML(o,kind){const items=o[kind+'History']??[];return items.length?`<details class="sectiongap"><summary>Frühere Fassungen (${items.length})</summary>${items.slice().reverse().map(p=>`<details class="protocolreview"><summary>${p.customerSignature?'Unterschrieben':'Entwurf'} · gespeichert ${date(p.savedAt??p.at)} · ersetzt ${date(p.replacedAt)}</summary>${protocolSummaryHTML(p,{kind})}${signatureImage(p.customerSignature)}</details>`).join('')}</details>`:'';}
function paymentDetail(o){const ps=o.payments??[],sum=ps.filter(p=>!p.cancelledAt).reduce((n,p)=>n+p.amountCents,0);const total=billingTotal(o);return pairs({'Festpreis':o.offer?money(o.offer.totalCents):'Noch kein Angebot','Eingegangen':money(sum),'Abrechnungsbetrag':total!==undefined?money(total):'—','Noch offen':total!==undefined?money(Math.max(0,total-sum)):'—'})+`${state.settings.standaloneAuth&&o.offer&&['Erledigt','Bezahlt'].includes(o.status)?invoiceDraftSummaryHTML(o):''}${o.invoice?invoiceResultHTML(o):['Erledigt','Bezahlt'].includes(o.status)&&state.settings.standaloneAuth&&state.integrationReady?.qonto&&state.settings.numberAudit&&!o.synthetic?'<button class="primary" data-click="invoice">Abrechnen · Rechnung oder Quittung</button><p class="hint">Rechnung mit 7 Tagen Zahlungsziel oder Quittung, wenn bereits bar oder per Karte bezahlt.</p>':'<p class="hint">Abrechnen mit Qonto: nach der Rückgabe und mit geprüfter Qonto-Verbindung (Einstellungen).</p>'}${ps.length?'<div class="sectiontitle">Zahlungen</div><ul class="timeline">'+ps.map((p,i)=>`<li class="${p.cancelledAt?'cancelled':''}">${money(p.amountCents)} · ${esc(p.method)}${p.cancelledAt?' · storniert':''}<small>${date(p.at)}${p.note?' · '+esc(p.note):''}${p.receipt?` · <a href="/api/asset/${esc(p.receipt)}" target="_blank" rel="noreferrer">Beleg</a>`:''}${p.history?.length?' · '+p.history.length+'× korrigiert':''}</small><span class="actions"><button class="smallbtn" data-payment-edit="${i}">Korrigieren</button>${p.cancelledAt?`<button class="smallbtn" data-payment-reactivate="${i}">Storno aufheben</button>`:`<button class="smallbtn danger" data-payment-cancel="${i}">Stornieren</button>`}</span></li>`).join('')+'</ul>':''}<form id="paymentform" class="sectiongap"><div class="sectiontitle">Zahlung erfassen</div><div class="grid2">${input('Betrag in €','amount','text',total&&total>sum?euro(total-sum):'','inputmode="decimal" placeholder="z. B. 349,00"')}${input('Zahlungszeitpunkt','at','datetime-local',berlinLocal())}<label>Zahlungsart<select name="method"><option>Bar</option><option>Karte</option><option>Überweisung</option></select></label><label>Beleg (optional)<input name="receipt" type="file" accept="image/*"></label></div>${input('Notiz','note','text','')}<label class="check"><input name="cashConfirmed" type="checkbox">Bei Bargeld: Eingang bestätigt.</label><label class="check"><input name="allowOverpayment" type="checkbox">Überzahlung / Trinkgeld ausdrücklich zulassen.</label><button class="primary" type="submit">Zahlung speichern</button><div class="error" id="form-error"></div></form>`;}
function notesDetail(o){return `<form id="noteform"><div class="grid2"><label>Art<select name="kind"><option>Notiz</option><option>Telefonat</option><option>Rückfrage</option><option>Protokollergänzung</option><option>Wiedervorlage</option></select></label>${input('Wiedervorlage (optional)','followUp','date')}</div><label>Notiz / Ergänzung<textarea name="note" placeholder="Besprochenes, Rückfrage oder nächsten Schritt festhalten"></textarea></label><button class="primary">In der Kundenakte speichern</button><div class="error" id="form-error"></div></form><div class="sectiontitle">Betreuungsverlauf</div><ul class="timeline">${(o.notes??[]).slice().reverse().map(n=>`<li><small>${date(n.at)} · ${esc(n.kind)}${n.followUp?' · Wiedervorlage '+esc(n.followUp):''}</small>${esc(n.note)}</li>`).join('')||'<li class="hint">Noch keine Notizen.</li>'}</ul><form id="statusform" class="formsection card sectiongap"><h3>Status bearbeiten</h3><p class="hint">Als Admin kannst du jeden Status direkt setzen. Die Änderung wird mit Grund im Verlauf festgehalten. Überspringst du eine fehlende Kundenunterschrift (Angebot oder Termin), ist der Grund Pflicht und gilt als deine Freigabe.</p><div class="grid2"><label>Neuer Status<select name="status">${STATES.map(s=>`<option ${s===o.status?'selected':''}>${s}</option>`).join('')}</select></label>${input('Grund (bei Freigabe ohne Unterschrift Pflicht)','reason','text','')}</div><button type="submit">Status speichern</button><div class="error"></div></form>${(o.statusHistory??[]).length?`<details class="sectiongap"><summary>Statusverlauf</summary><ul class="timeline">${o.statusHistory.slice().reverse().map(h=>`<li><small>${date(h.at)}</small>${esc(h.from)} → ${esc(h.to)}${h.reason?' · '+esc(h.reason):''}</li>`).join('')}</ul></details>`:''}<div class="actions sectiongap"><button data-click="audit">Änderungsprotokoll ansehen</button>${o.status!=='Bezahlt'&&o.status!=='Storniert'?'<button class="danger" data-click="cancel">Auftrag stornieren</button>':''}${state.settings.standaloneAuth&&o.status==='Storniert'&&o.appointment&&!o.synthetic?'<button data-click="calendarSync">Google-Stornierung abgleichen</button>':''}${state.settings.standaloneAuth&&!o.synthetic?'<button data-click="reconcile">Anbieterresultat lesend prüfen</button>':''}</div>`;}
function modal(title,content,footer=''){const m=$('#modal');m.innerHTML=`<div class="modalhead"><h2>${title}</h2><button data-click="close" aria-label="Schließen">×</button></div><div class="modalbody">${content}</div>${footer?`<div class="modalfooter">${footer}</div>`:''}`;if(!m.open)m.showModal();return m;}
function createModal(){manualCreateModal({synthetic,modal});}
const bookingFormStates=new WeakMap();
function bookingFormState(form){return JSON.stringify([...form.querySelectorAll('input,select,textarea')].map(field=>[field.name,field.type,field.value,field.checked]));}
function bookingFormDirty(form){return Boolean(form&&(form.dataset.dirty==='true'||bookingFormStates.get(form)!==bookingFormState(form)));}
function requireSavedBooking(){for(const [id,message] of [['priceform','Bitte geänderte Leistungen und Preise zuerst speichern.'],['appointmentform','Bitte den geänderten Termin zuerst speichern.']]){const form=document.getElementById(id);if(bookingFormDirty(form))throw Object.assign(Error(message),{formError:form.querySelector('.error')});}}
async function action(name,input={}){const sibling=name==='price'?$('#appointmentform'):name==='appointment'?$('#priceform'):null;const keepSibling=bookingFormDirty(sibling)?sibling:null;const o=await api('action',{id:selected.id,version:selected.version,action:name,input});selected=o;state=await api('state');render();if(keepSibling)document.getElementById(keepSibling.id)?.replaceWith(keepSibling);return o;}
async function uploadFile(file,kind='photo',orderId=selected.id){const r=await fetch('/api/upload/'+encodeURIComponent(orderId)+'?kind='+kind+(kind==='signature'?'&draft='+protocolDraft.id+'&hash='+protocolDraft.hash:''),{method:'POST',headers:{'Content-Type':file.type},body:file});const d=await r.json().catch(()=>({error:r.status===413?'Datei ist zu groß (höchstens 15 MB).':'Upload nicht bestätigt.'}));if(!r.ok)throw Error(d.error??'Upload fehlgeschlagen.');return d.id;}
function signModal(title,summary,extra=''){const m=modal(title,`${summary}<form id="signform">${signatureBox('customerSign','Unterschrift Kunde')}${extra}<div class="error" id="modal-error"></div><button class="primary" type="submit">Unterschrift speichern</button></form>`);const pads=mountSignatures(m);return pads.customerSign;}
let activePad=null,signContext=null;
async function sharePdf(kind){const r=await fetch('/api/protocol/pdf?id='+encodeURIComponent(selected.id)+'&kind='+kind);if(!r.ok)throw Error('PDF konnte nicht erstellt werden.');const file=new File([await r.blob()],selected.wg+'-'+({intake:'Annahmeprotokoll',return:'Rueckgabeprotokoll',acceptance:'Auftragsbestaetigung'})[kind]+'.pdf',{type:'application/pdf'});if(navigator.canShare?.({files:[file]})){await navigator.share({files:[file],title:file.name});return;}const link=document.createElement('a');link.href=URL.createObjectURL(file);link.download=file.name;link.click();setTimeout(()=>URL.revokeObjectURL(link.href),10000);}
document.addEventListener('click',async e=>{if(isOffer||isDocument||isInvoicePage)return;const v=e.target.closest('[data-view]'),order=e.target.closest('[data-order]'),tb=e.target.closest('[data-tab]'),f=e.target.closest('[data-filter]'),check=e.target.closest('[data-check]'),click=e.target.closest('[data-click]'),customer=e.target.closest('[data-customer]'),newOrder=e.target.closest('[data-new-order]'),payEdit=e.target.closest('[data-payment-edit]'),payCancel=e.target.closest('[data-payment-cancel]'),payReactivate=e.target.closest('[data-payment-reactivate]');try{
  if(v){e.preventDefault();view=v.dataset.view;selected=null;history.replaceState(null,'','#'+view);$('.sidebar')?.classList.remove('open');render();return;}
  if(customer){e.preventDefault();await customerModal(customer.dataset.customer);return;}
  if(newOrder){e.preventDefault();await newOrderFor(newOrder.dataset.newOrder);return;}
  if(order){e.preventDefault();$('#modal').open&&$('#modal').close();await openOrder(order.dataset.order);return;}
  if(tb){tab=tb.dataset.tab;replacing=null;render();return;}if(f){filter=f.dataset.filter;render();return;}
  if(payEdit){const p=selected.payments[Number(payEdit.dataset.paymentEdit)];modal('Zahlung korrigieren',`<form id="paymenteditform" data-index="${payEdit.dataset.paymentEdit}"><div class="grid2">${input('Betrag in €','amount','text',euro(p.amountCents),'inputmode="decimal"')}${input('Zahlungszeitpunkt','at','datetime-local',berlinLocal(p.at))}<label>Zahlungsart<select name="method">${['Bar','Karte','Überweisung'].map(m=>`<option ${m===p.method?'selected':''}>${m}</option>`).join('')}</select></label>${input('Notiz','note','text',p.note??'')}</div><label class="check"><input name="allowOverpayment" type="checkbox">Überzahlung / Trinkgeld ausdrücklich zulassen.</label><p class="hint">Die bisherige Angabe bleibt im Verlauf der Zahlung erhalten.</p><button class="primary" type="submit">Korrektur speichern</button><div class="error" id="modal-error"></div></form>`);return;}
  if(payReactivate){const index=Number(payReactivate.dataset.paymentReactivate),p=selected.payments[index];await action('paymentEdit',{id:p.id,index,reactivate:true});toast('Storno aufgehoben. Die Zahlung zählt wieder.');return;}
  if(payCancel){const p=selected.payments[Number(payCancel.dataset.paymentCancel)];await action('paymentEdit',{id:p.id,index:Number(payCancel.dataset.paymentCancel),cancelled:true});toast('Zahlung storniert. Sie bleibt im Verlauf sichtbar.');return;}
  if(check){$('#settings-error').textContent='';const form=$('#settingsform');const data=formData(form);const fields={website:['hubKey'],email:['resendKey','sender','reviewUrl'],calendar:['calendarProvider','calendarId','calendarToken'],qonto:['qontoLogin','qontoKey']}[check.dataset.check];check.disabled=true;try{await api('settings',Object.fromEntries(fields.map(k=>[k,data[k]])));const r=await api('check',{kind:check.dataset.check});toast(r.message);state=await api('state');for(const key of fields)if(form.elements[key]?.type==='password')form.elements[key].value='';if(check.dataset.check==='qonto')render();}finally{check.disabled=false;}return;}
  if(!click)return;const k=click.dataset.click,kind=click.dataset.kind;
  if(['onsiteAccept','confirm','confirmPrice','replaceOffer','signPending','confirmAppointmentSign','confirmAppointmentRelease','sendOffer','sendOfferConfirmed','offerLink','renewOfferLink'].includes(k))requireSavedBooking();
  if(k==='portalRequest'){const r=await api('portal-admin/request',{id:click.dataset.request,decision:click.dataset.decision});toast(r.message??(click.dataset.decision==='decline'?'Kundenwunsch abgelehnt.':'Kundenwunsch erledigt.'));await refresh();return;}
  if(k==='logout'){const response=await fetch('/auth/logout',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});if(!response.ok)throw Error('Abmeldung nicht bestätigt.');location.assign('/auth/login');return;}
  if(k==='menu')setMenu(!$('.sidebar').classList.contains('open'),click);if(k==='menuClose')setMenu(false);if(k==='close')$('#modal').close();if(k==='back'){selected=null;history.replaceState(null,'','#');render();}if(k==='refresh')await refresh();
  if(k==='newCustomer')await customerModal(null);
  if(k==='linkCustomer'){modal('Kunden zuordnen',`<label>Kunde suchen<input id="link-search" type="search" placeholder="Name, Telefon, E-Mail oder Kennzeichen"></label><div id="link-results"></div><p class="hint">Oder neuen Kunden aus den Auftragsangaben anlegen:</p><button data-click="linkNewCustomer">Neuen Kunden anlegen und zuordnen</button><div class="error" id="modal-error"></div>`);$('#link-search').addEventListener('input',async ev=>{const found=(await api('customers?q='+encodeURIComponent(ev.target.value)+(selected.synthetic?'&test=true':''))).customers;$('#link-results').innerHTML=found.map(c=>`<div class="row"><span>${esc(c.name||c.company||'Ohne Namen')} · ${esc(c.phone||c.email||'')}</span><button class="smallbtn" data-click="linkTo" data-id="${c.id}" data-vehicle="${esc(c.vehicles[0]?.id??'')}">Zuordnen</button></div>`).join('')||'<p class="hint">Kein Kunde gefunden.</p>';});}
  if(k==='linkTo'){selected=await api('link',{orderId:selected.id,customerId:click.dataset.id,vehicleId:click.dataset.vehicle||null});$('#modal').close();await refresh();toast('Kunde zugeordnet.');}
  if(k==='linkNewCustomer'){const s=selected.source;const c=await api('customer',{synthetic:selected.synthetic,customer:{name:s.name,company:s.company,phone:s.phone,email:s.email,address:s.address,city:s.city,reviewConsent:s.reviewConsent}});const veh=s.vehicle||s.plate?await api('vehicle',{customerId:c.id,vehicle:{label:s.vehicle,plate:s.plate}}):null;selected=await api('link',{orderId:selected.id,customerId:c.id,vehicleId:veh?.id??null});$('#modal').close();await refresh();toast('Kunde angelegt und zugeordnet.');}
  if(k==='qontoNumbers'){const r=await api('qonto/numbers',{});await refresh();toast(r.count+' Qonto-Rechnungen gelesen; höchste WG-Nummer '+r.maxNumber+'. Bisherige Buchungen zusätzlich abgleichen.');}
  if(k==='background'){const r=await api('background',{});await refresh();toast(r.deliveryError??'Angebote & Fälligkeiten geprüft.');}if(k==='migration'){const fingerprint=await downloadMigration();toast('Verschlüsselte Übertragung erstellt. Serverschlüssel: '+fingerprint.slice(0,16));}
  if(k==='calendarConnect'){const response=await fetch('/auth/calendar/start',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});const result=await response.json();if(!response.ok)throw Error(result.error??'Google-Verbindung konnte nicht begonnen werden.');const authorization=new URL(result.authorizationUrl);if(authorization.origin!=='https://accounts.google.com'||authorization.pathname!=='/o/oauth2/v2/auth')throw Error('Google-Anmeldeziel konnte nicht geprüft werden.');location.assign(authorization.href);return;}
  if(k==='calendarSync'){await action('calendarSync');toast('Google-Termin abgeglichen.');}
  if(k==='invoiceDraft'){modal('Rechnungsentwurf bearbeiten · '+esc(selected.wg),invoiceDraftForm(selected));mountInvoiceDraftForm($('#invoiceDraftform'));}if(k==='invoice'){const invoiceOrder=structuredClone(selected);const inventory=await api('qonto/clients?id='+encodeURIComponent(invoiceOrder.id));if(selected?.id!==invoiceOrder.id||selected?.version!==invoiceOrder.version)throw Error('Der Auftrag hat sich geändert. Bitte erneut öffnen.');modal('Abrechnen · '+esc(invoiceOrder.wg),invoiceForm(invoiceOrder,inventory));mountInvoiceForm($('#invoiceform'),invoiceOrder,inventory);}
  if(k==='invoiceSync'){const r=await action('invoiceSync');toast(r.invoiceMessage??'Zahlstatus abgeglichen.');}
  if(k==='invoiceMarkPaid'){const r=await action('invoiceMarkPaid');toast(r.invoiceMessage??'In Qonto als bezahlt markiert.');}
  if(k==='invoiceMail')modal('Rechnung per E-Mail senden',`<p>Empfänger: ${esc(selected.source.email||'Keine E-Mail hinterlegt')}</p><p>${esc(selected.invoice?.number??'')} · PDF im Anhang, Kopie an dich.</p><div id="modal-error" class="error"></div>`,`<button data-click="close">Zurück</button><button class="primary" data-click="invoiceMailConfirmed">Jetzt senden</button>`);
  if(k==='invoiceMailConfirmed'){click.disabled=true;try{const r=await action('invoiceMail');$('#modal').close();toast(r.invoiceMessage??'Versand angefordert.');}finally{click.disabled=false;}}
  if(k==='invoiceReminder')modal('Mahnstufe senden',`<p>Empfänger: ${esc(selected.source.email||'Keine E-Mail hinterlegt')}</p><p>${esc(selected.invoiceInfo?.pending?.label??selected.invoiceInfo?.next?.label??'Zahlungserinnerung')} zu ${esc(selected.invoice?.number??'')}. Vorher wird der Zahlstatus in Qonto geprüft; bei Zahlungseingang entfällt die E-Mail.</p><div id="modal-error" class="error"></div>`,`<button data-click="close">Zurück</button><button class="primary" data-click="invoiceReminderConfirmed">Jetzt senden</button>`);
  if(k==='invoiceReminderConfirmed'){click.disabled=true;try{const r=await action('invoiceReminder');$('#modal').close();toast(r.invoiceMessage??'Versand angefordert.');}finally{click.disabled=false;}}
  if(k==='invoicePortal'){const url=click.dataset.url;try{await navigator.clipboard.writeText(url);toast('Kundenlink kopiert. Der Kunde meldet sich mit seiner E-Mail-Adresse an.');}catch{window.prompt('Kundenlink',url);}}

  if(k==='sendOffer')modal('Angebot versenden',`<p>Empfänger: ${esc(selected.source.email||'Keine E-Mail hinterlegt')}</p><p>${esc(selected.wg)} · ${money(selected.offer.totalCents)} brutto</p><p>Der Kunde erhält den persönlichen Link und seine einmalige PIN in derselben E-Mail.</p><div id="modal-error" class="error"></div>`,`<button data-click="close">Zurück</button><button class="primary" data-click="sendOfferConfirmed">Angebot jetzt senden</button>`);if(k==='sendOfferConfirmed'){click.disabled=true;await action('sendOffer');$('#modal').close();toast('Resend hat den Angebotsversand bestätigt.');}
  if(k==='renewOfferLink'){await action('renewOfferLink');toast('Neuer persönlicher Angebotslink erstellt.');}if(k==='offerLink'){const link=location.origin+'/angebot/'+selected.offerToken;const wa=whatsapp(selected.source.phone);modal('Persönlicher Angebotslink',`<p>${esc(selected.source.name)} · ${esc(selected.source.email||'Kunden-E-Mail fehlt')}</p><label>Angebotslink<input readonly value="${esc(link)}"></label>${wa?`<a class="button" target="_blank" rel="noreferrer" href="${esc(wa+'?text='+encodeURIComponent('Ihr Angebot von White Gloss: '+link))}">Per WhatsApp senden</a>`:''}<p>Der Kunde meldet sich mit seiner E-Mail-Adresse an und erhält eine einmalige PIN. Er sieht ausschließlich sein eigenes Angebot.</p>`);}
  if(k==='orderChat'){const id=await openChatForOrder(selected.id);selected=null;view='chat';chatThread=id;history.replaceState(null,'','#chat='+id);render();}
  if(k==='test'){synthetic=!synthetic;selected=null;customers=[];leaveInbox();render();}if(k==='create')createModal();
  if(k==='import'){if(synthetic)throw Error('Website-Import ist im Testbereich gesperrt.');const r=await api('import',{});toast(`${r.created} neue Anfragen, ${r.updated} aktualisiert, ${r.checked} geprüft, ${r.skipped??0} bestehende Anfragen ausgelassen.`);await refresh();}

  if(k==='confirm')modal('Fixpreis freigeben',`<p>Leistungen: ${esc(selected.assessment?.services||'—')}</p><p><strong>Gesamtfestpreis: ${money(selected.assessment?.totalCents)}</strong></p>${priceNoteHTML()}<p class="hint">Danach kann der Kunde online annehmen. Solange er nicht unterschrieben hat, kannst du die Preise weiter anpassen.</p><div id="modal-error" class="error"></div>`,`<button data-click="close">Zurück</button><button class="primary" data-click="confirmPrice">Fixpreis freigeben</button>`);if(k==='confirmPrice'){await action('confirm');$('#modal').close();toast('Fixpreis freigegeben.');}
  if(k==='reject')modal('Anfrage ablehnen','<form id="rejectform"><label>Grund (optional)<textarea name="reason"></textarea></label><button class="danger">Ablehnung speichern</button><div id="modal-error" class="error"></div></form>');
  if(k==='bookingphotos'){await loadBookingPhotos($('#websitephotos'),selected.id);}
  if(k==='websitephotos'){const photos=await api('websitephotos/'+selected.id);$('#websitephotos').innerHTML=photos.length?photos.map(p=>p.mime.startsWith('image/')?`<a href="${esc(p.url)}" target="_blank" rel="noreferrer"><img src="${esc(p.url)}" alt="${esc(p.name)}"></a>`:`<a href="${esc(p.url)}" target="_blank" rel="noreferrer">${esc(p.name)} · Video öffnen</a>`).join(''):'<p class="hint">Keine Website-Fotos verfügbar.</p>';}
  if(k==='cancel')modal('Auftrag stornieren','<form id="cancelform"><label>Grund der Stornierung (optional)<textarea name="reason"></textarea></label><p>Ein vorhandener eigener Google-Termin wird nach freigegebenem Kalenderabgleich aufgehoben. Kundennachrichten werden hier nicht versendet. Über „Status bearbeiten“ lässt sich der Auftrag wieder aktivieren.</p><button class="danger">Stornierung speichern</button><div class="error" id="modal-error"></div></form>');
  if(k==='reconcile'){await action('reconcile');toast('Vorhandene Anbieterresultate gelesen.');}
  if(k==='deleteOrder')modal('Auftrag löschen',`<p>${esc(selected.wg)} · ${esc(selected.source.name)}</p><p>Der Auftrag wird in den Papierkorb verschoben und kann wiederhergestellt werden. Dokumente, Unterschriften, Rechnungen und Fotos bleiben erhalten. Kundenlinks und automatische Abläufe werden gestoppt.</p><form id="deleteorderform"><label>Grund (optional)<input name="reason" maxlength="2000"></label><div class="error"></div><button class="danger" type="submit">In den Papierkorb verschieben</button></form>`);if(k==='restoreOrder'){await action('restoreOrder');toast('Auftrag wiederhergestellt. Bisherige Kundenlinks bei Bedarf neu erstellen.');}if(k==='audit'){const audit=await api('audit');modal('Dauerhaftes Änderungsprotokoll','<ul class="timeline">'+audit.filter(a=>a.order_id===selected.id).map(a=>`<li><small>${date(a.at)} · ${esc(a.actor)} · Version ${a.version}</small>${esc(a.action)} → ${esc(a.status)}</li>`).join('')+'</ul>');}
  if(k==='prevMonth'){calendarOffset--;render();}if(k==='nextMonth'){calendarOffset++;render();}if(k==='today'){calendarOffset=0;render();}
  if(k==='confirmAppointmentSign'){const a=selected.appointment;signContext={kind:'appointment'};activePad=signModal('Kunde bestätigt den Termin',`<div class="protocolreview"><p><strong>Termin: ${date(a.start)}</strong><br>voraussichtlich fertig: ${date(a.end)}<br>${esc(a.delivery)}${a.location?' · '+esc(a.location):''}</p></div>`,`<label class="check"><input type="checkbox" name="confirmed">Ich bestätige diesen Termin verbindlich.</label>${input('Name des Kunden','customerName','text',selected.source.name)}`);}
  if(k==='confirmAppointmentRelease')modal('Termin ohne Unterschrift verbindlich machen','<form id="appointmentreleaseform"><p>Der Kunde hat den Termin nicht unterschrieben. Mit deiner Freigabe wird er trotzdem verbindlich (z. B. telefonisch bestätigt). Der Grund wird dauerhaft im Auftrag gespeichert.</p><label>Grund<input name="releaseReason" required minlength="3" maxlength="300" placeholder="z. B. telefonisch am 15.10. bestätigt"></label><button class="primary">Termin verbindlich machen</button><div id="modal-error" class="error"></div></form>');
  if(k==='removeAppointment'){await action('appointment',{start:''});toast('Termin entfernt.');}
  if(k==='appointmentNow'){const form=$('#appointmentform');await action('appointment',{start:berlinLocal(),duration:Number(form.elements.duration.value)||defaultDuration(selected),delivery:form.elements.delivery.value,location:form.elements.location.value});toast('Termin beginnt jetzt.');}
  if(k==='onsiteAccept'){const o=selected,base=o.offer??o.assessment;signContext={kind:'onsite',displayedWithdrawalText:state.settings.withdrawalText??''};activePad=signModal(o.appointment?'Angebot & Termin gemeinsam unterschreiben':'Kunde unterschreibt vor Ort',`${base?offerLinesHTML(base)+`<p><strong>Gesamtfestpreis: ${money(base.totalCents)}</strong></p>`:'<p class="notice">Noch keine Preise gespeichert. Das Angebot wird mit 0,00 € angenommen.</p>'}${priceNoteHTML()}${o.appointment?`<section class="protocolreview sectiongap"><h3>Ihr Termin</h3><p><strong>${date(o.appointment.start)}</strong><br>voraussichtlich fertig: ${date(o.appointment.end)}<br>${esc(o.appointment.delivery)}${o.appointment.location?' · '+esc(o.appointment.location):''}</p></section>`:''}${state.settings.withdrawalText?`<details class="protocolreview" open><summary>Widerrufsbelehrung</summary><p class="withdrawal-text">${esc(state.settings.withdrawalText)}</p></details>`:''}`,`<label class="check"><input type="checkbox" name="paymentObligation">Ich nehme die angezeigten Leistungen zum Gesamtfestpreis zahlungspflichtig an.</label>${o.appointment&&!o.appointment.confirmation?'<label class="check"><input type="checkbox" name="confirmAppointment">Ich bestätige auch den oben angezeigten Termin verbindlich mit dieser Unterschrift.</label>':''}<label class="check"><input type="checkbox" name="immediateStart">${esc(immediateStartNotice)}</label>${state.settings.withdrawalText?'<label class="check"><input type="checkbox" name="withdrawalNotice">Die Widerrufsbelehrung wurde mir angezeigt.</label>':''}${input('Name des Kunden','customerName','text',o.source.name)}<details class="protocolreview"><summary>Kunde kann nicht unterschreiben?</summary><label class="check"><input type="checkbox" name="release">Ohne Kundenunterschrift freigeben (meine Verantwortung)</label>${input('Grund der Freigabe','releaseReason','text','')}</details>`);}
  if(k==='replaceOffer'){await action('replacement',{kind:'offer'});toast('Ersatzangebot erstellt. Es wartet auf die Unterschrift des Kunden.');}
  if(k==='replaceProtocol'){replacing=kind;render();$('#replacementform')?.scrollIntoView({behavior:'smooth'});}
  if(k==='signPending'){signContext={kind:'pending',document:kind,displayedWithdrawalText:state.settings.withdrawalText??''};const p=selected.pending[kind];activePad=signModal('Kunde unterschreibt das Dokument',`${kind==='offer'?offerLinesHTML(p.content)+`<p><strong>Gesamtfestpreis: ${money(p.content.totalCents)}</strong></p>`+priceNoteHTML():protocolSummaryHTML(p.content,{kind})}<p class="notice">${p.replaces?'Ersetzt ausdrücklich das '+(p.replaces.signedAt?'am '+date(p.replaces.signedAt)+' ':'')+'unterschriebene Dokument.':'Bitte das angezeigte Protokoll prüfen und persönlich unterschreiben.'}</p>`,kind==='offer'?`<label class="check"><input type="checkbox" name="paymentObligation">Ich nehme das Ersatzangebot zahlungspflichtig an.</label>${state.settings.withdrawalText?`<details class="protocolreview"><summary>Widerrufsbelehrung</summary><p class="withdrawal-text">${esc(state.settings.withdrawalText)}</p></details><label class="check"><input type="checkbox" name="withdrawalNotice">Die Widerrufsbelehrung wurde mir angezeigt.</label>`:''}<label class="check"><input type="checkbox" name="immediateStart">${esc(immediateStartNotice)}</label>`:'');}
  if(k==='documentLink'){await action('documentLink',{kind});toast('Persönlicher Link erstellt.');}
  if(k==='sendDocument')modal('Dokument zur Unterschrift senden',`<p>Empfänger: ${esc(selected.source.email||'Keine E-Mail hinterlegt')}</p><p>${esc(selected.wg)} · ${kind==='intake'?'Annahmeprotokoll':kind==='return'?'Übergabeprotokoll':'Korrekturangebot'}</p><p>Der Kunde erhält seinen persönlichen Zugang mit Link und PIN.</p><div id="modal-error" class="error"></div>`,`<button data-click="close">Zurück</button><button class="primary" data-click="sendDocumentConfirmed" data-kind="${kind}">Jetzt senden</button>`);if(k==='sendDocumentConfirmed'){click.disabled=true;await action('sendDocument',{kind});$('#modal').close();toast('Dokument mit persönlichem Link und PIN versendet.');}
  if(k==='discardPending'){await action('discardReplacement',{kind});toast('Unterschriftsanfrage verworfen. Gespeicherte Dokumente bleiben erhalten.');}
  if(k==='sharePdf')await sharePdf(kind);
}catch(err){const el=err.formError??$('#modal[open] #modal-error')??$('#form-error')??$('#settings-error');if(el){el.textContent=err.message;el.setAttribute('role','alert');if(err.formError)el.scrollIntoView({block:'center'});}else toast(err.message);}});
function formData(form){return Object.fromEntries(new FormData(form));}
function settingsData(form){const d=formData(form);d.lastNumber=Number(d.lastNumber??0);d.numberAudit=form.elements.numberAudit?.checked===true;for(const key of ['sendApproved','backgroundApproved','autoImportApproved','calendarSyncApproved','dunningApproved'])if(form.elements[key])d[key]=form.elements[key].checked;return d;}
function berlinInputToISO(local){const base=Date.parse(local+'Z');const fmt=new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Berlin',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'});const matches=[60,120].map(n=>new Date(base-n*60000)).filter(d=>fmt.format(d).replace(' ','T')===local);if(matches.length!==1)throw Error('Uhrzeit ist ungültig oder bei der Zeitumstellung doppeldeutig.');return matches[0].toISOString();}
document.addEventListener('submit',async e=>{if(isOffer||isDocument||isInvoicePage)return;e.preventDefault();const f=e.target;const submit=e.submitter??f.querySelector('[type=submit]')??f.querySelector('button:not([type=button])');if(submit)submit.disabled=true;try{const d=formData(f);
  if(f.id==='settingsform'){await api('settings',settingsData(f));await refresh();toast('Einstellungen geschützt gespeichert. Verbindungen separat prüfen.');}
  if(f.id==='createform'){const selection=readManualSelection(f);for(const key of ['extraIds','packageId','classId','citySlug','pickupKm','customPickupEuro','customerId','vehicleId'])delete d[key];d.reviewConsent=f.elements.reviewConsent.checked;const created=await api('create',{source:d,selection,synthetic,customerId:f.elements.customerId?.value||null,vehicleId:f.elements.vehicleId?.value||null});$('#modal').close();state=await api('state');selected=created;tab='source';history.replaceState(null,'','#auftrag='+created.id);render();toast('Anfrage dauerhaft gespeichert.');}
  if(f.id==='customerform'){const customer={...d,reviewConsent:f.elements.reviewConsent.checked};const saved=await api('customer',{id:f.dataset.id||undefined,version:f.dataset.version?Number(f.dataset.version):undefined,customer,synthetic});await customerModal(saved.id);await loadCustomers();toast('Kunde gespeichert.');}
  if(f.classList.contains('vehicleform')){const saved=await api('vehicle',{id:f.dataset.id||undefined,version:f.dataset.version?Number(f.dataset.version):undefined,customerId:f.dataset.customer||undefined,vehicle:d});await customerModal(saved.customerId);await loadCustomers();toast('Fahrzeug gespeichert.');}
  if(f.id==='sourceform'){await action('editSource',{source:{...d,reviewConsent:f.elements.reviewConsent.checked}});toast('Angaben gespeichert.');}
  if(f.id==='priceform'){await action('price',readPricing(f));toast('Leistungen und Preise gespeichert.');}
  if(f.id==='bookingphotoform'){for(const file of f.elements.bookingphotos.files)await uploadFile(file,'booking');await loadBookingPhotos($('#websitephotos'),selected.id);f.reset();toast('Buchungsfotos geschützt gespeichert.');}
  if(f.id==='invoiceDraftform'){await action('invoiceDraft',invoiceDraftInput(f));$('#modal').close();toast('Rechnungsentwurf gespeichert. Vor dem Ausstellen unter Abrechnen prüfen.');}if(f.id==='invoiceform'){const r=await action('invoice',invoiceInput(f,selected));$('#modal').close();toast(r.invoiceMessage??(r.invoice?.mode==='paid'?'Quittung ausgestellt und Zahlung erfasst.':'Rechnung ausgestellt.'));}
  if(f.id==='appointmentform'){if(!d.start)throw Error('Bitte Datum und Uhrzeit wählen oder „Termin entfernen“ nutzen.');const saved=await action('appointment',{...d,release:f.elements.release?.checked===true,releaseReason:d.releaseReason??'',duration:Number(d.duration)||defaultDuration(selected)});toast(saved.appointment?.confirmation?'Termin gespeichert.':'Termin gespeichert – wartet auf die Bestätigung des Kunden (Kundenportal oder Unterschrift vor Ort).');}
  if(f.id==='noteform'){await action('note',d);toast('Kundenakte ergänzt.');}
  if(f.id==='statusform'){await action('setStatus',d);toast('Status gespeichert.');}
  if(f.id==='deleteorderform'){await action('deleteOrder',d);$('#modal').close();selected=null;view='orders';history.replaceState(null,'','#orders');render();toast('Auftrag in den Papierkorb verschoben.');}if(f.id==='cancelform'){await action('cancel',d);$('#modal').close();toast('Stornierung gespeichert.');}
  if(f.id==='rejectform'){await action('reject',d);$('#modal').close();toast('Ablehnung gespeichert.');}
  if(f.id==='paymentform'){const amountCents=euroCents(d.amount);if(!amountCents)throw Error('Bitte den eingegangenen Betrag in Euro angeben.');const receipt=f.elements.receipt.files[0]?await uploadFile(f.elements.receipt.files[0],'receipt'):null;await action('payment',{amountCents,at:d.at?berlinInputToISO(d.at):undefined,method:d.method,note:d.note,receipt,cashConfirmed:f.elements.cashConfirmed.checked,allowOverpayment:f.elements.allowOverpayment.checked});toast('Zahlung gespeichert: '+money(amountCents)+'.');}
  if(f.id==='paymenteditform'){const index=Number(f.dataset.index),p=selected.payments[index];await action('paymentEdit',{id:p.id,index,amountCents:euroCents(d.amount),at:d.at?berlinInputToISO(d.at):undefined,method:d.method,note:d.note,allowOverpayment:f.elements.allowOverpayment.checked});$('#modal').close();toast('Zahlung korrigiert.');}
  if(f.id==='replacementform'){const kind=f.dataset.kind;const protocol=await collectProtocol(f,uploadFile,selected.pending?.[kind]?.content??selected[kind]);await action('replacement',{kind,protocol});replacing=null;render();toast('Korrekturentwurf gespeichert. Das unterschriebene Original gilt bis zur neuen Kundenunterschrift weiter.');}
  if(f.id==='protocolform'){const kind=f.dataset.kind;const protocol=await collectProtocol(f,uploadFile,selected.pending?.[kind]?.content??selected[kind]);if(submit?.dataset.submit==='remote'){await action('protocolRequest',{kind,protocol});toast('Protokoll zur Kundenunterschrift vorbereitet. Persönlichen Link erstellen oder E-Mail senden.');}else if(submit?.dataset.submit!=='sign'){const o=await action(kind,{protocol});toast(o.protocolDelivery?.message??'Protokoll gespeichert.');}else{protocolDraft=await api('protocol/prepare',{id:selected.id,version:selected.version,kind,protocol});const m=modal('Protokoll prüfen & unterschreiben',`<div class="protocolreview">${protocolSummaryHTML(protocolDraft.protocol,{kind})}</div><p class="hint">Die Unterschriften werden genau diesem angezeigten Protokoll zugeordnet. Eine Unterschrift ist nicht zwingend; ohne Kundenunterschrift bleibt das Protokoll bearbeitbar.</p><form id="signatureform"><div class="grid2">${signatureBox('customerSign','Unterschrift Kunde')}${signatureBox('operatorSign','Unterschrift Betrieb')}</div><label class="check sectiongap"><input type="checkbox" name="confirmed">Das angezeigte Protokoll wurde persönlich geprüft.</label><div id="modal-error" class="error"></div><button type="submit" class="primary">Protokoll speichern</button></form>`);signContext={kind:'protocol',pads:mountSignatures(m)};}}
  if(f.id==='signatureform'){const pads=signContext.pads,customer=await pads.customerSign.file('Kunde'),operator=await pads.operatorSign.file('Betrieb');const customerSignature=customer?await uploadFile(customer,'signature'):null;const operatorSignature=operator?await uploadFile(operator,'signature'):null;const o=await action(protocolDraft.protocol.kind??$('#protocolform')?.dataset.kind,{draftId:protocolDraft.id,snapshotHash:protocolDraft.hash,customerSignature,operatorSignature,signaturesConfirmed:f.elements.confirmed.checked});$('#modal').close();protocolDraft=null;toast(o.protocolDelivery?.message??'Protokoll gespeichert.');}
  if(f.id==='appointmentreleaseform'){await action('confirmAppointment',{release:true,releaseReason:f.elements.releaseReason.value});$('#modal').close();toast('Termin ohne Unterschrift verbindlich gemacht. Der Grund ist im Auftrag gespeichert.');}
  if(f.id==='signform'){const signature=activePad?.dataURL();if(signContext.kind==='appointment'){if(!f.elements.confirmed.checked)throw Error('Bitte die Bestätigung des Kunden ankreuzen lassen.');if(!signature)throw Error('Bitte den Kunden unterschreiben lassen.');await action('confirmAppointment',{signature,inPerson:true,customerName:f.elements.customerName.value});$('#modal').close();toast('Termin vom Kunden vor Ort bestätigt.');}else if(signContext.kind==='onsite'){if(!signature&&!f.elements.release?.checked)throw Error('Bitte den Kunden unterschreiben lassen – oder „Ohne Kundenunterschrift freigeben“ mit Grund wählen.');if(signature&&selected.appointment&&!selected.appointment.confirmation&&!f.elements.confirmAppointment?.checked)throw Error('Bitte Angebot und angezeigten Termin gemeinsam bestätigen.');const accepted=await action('onsiteAccept',{release:!signature&&f.elements.release?.checked===true,releaseReason:f.elements.releaseReason?.value??'',displayedWithdrawalText:signContext.displayedWithdrawalText,signature,paymentObligation:f.elements.paymentObligation?.checked===true,immediateStart:f.elements.immediateStart?.checked===true,withdrawalNotice:f.elements.withdrawalNotice?.checked===true,customerName:f.elements.customerName?.value??'',confirmAppointment:f.elements.confirmAppointment?.checked===true});$('#modal').close();toast((signature?'Angebot vor Ort unterschrieben.':'Angebot mit deiner Freigabe ohne Unterschrift angenommen.')+' '+(accepted.protocolDelivery?.message??''));}else{if(!signature)throw Error('Bitte das angezeigte Dokument persönlich unterschreiben.');const o=await action('signReplacement',{displayedWithdrawalText:signContext.displayedWithdrawalText,kind:signContext.document,signature,inPerson:true,paymentObligation:f.elements.paymentObligation?.checked===true,immediateStart:f.elements.immediateStart?.checked===true,withdrawalNotice:f.elements.withdrawalNotice?.checked===true});if(o.protocolDelivery?.state==='sent')toast(o.protocolDelivery.message);$('#modal').close();toast('Dokument unterschrieben und gespeichert.');}}
}catch(err){const el=f.querySelector('.error')??$('#modal-error');if(el)el.textContent=err.message;else toast(err.message);}finally{if(submit)submit.disabled=false;}});
async function start(){const hash=location.hash.slice(1);if(hash==='chat'||hash.startsWith('chat=')){view='chat';chatThread=/^chat=[0-9a-f-]{36}$/.test(hash)?hash.slice(5):null;}if(view==='chat'&&!state.settings.standaloneAuth)view='overview';await refresh();if(state.settings.standaloneAuth)startChatBadge(()=>synthetic);if(hash.startsWith('auftrag='))await openOrder(decodeURIComponent(hash.slice(8))).catch(error=>toast(error.message));else if(menus.some(m=>m[0]===hash)){view=hash;render();}}
(isOffer?showOffer():isDocument?showDocument():isInvoicePage?showInvoicePage():start()).catch(err=>{$('#app').innerHTML=`<div class="appoff card"><span class="brandmark">WG</span><h1>Dein privates Panel</h1><p>${esc(err.message)}</p><p class="hint">Bitte mit deinem Betreiberkonto anmelden. Kundendaten werden ohne berechtigten Zugang nicht geladen.</p><button data-click="refresh">Erneut prüfen</button></div>`;});
